/*===========================================================================

FUNCTION cmss_update_stack_1_no_srv_ind_info

DESCRIPTION
  Update the phone object per the new service indicators.

DEPENDENCIES
  Phone object must have already been initialized with
  cmph_init().

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/

static void cmss_update_stack_1_no_srv_ind_info(

  const sd_si_info_s_type   *si_info_ptr,
  /* Pointer to buffer containing new service info information */

  sys_modem_as_id_e_type     asubs_id
)
{
  sys_band_class_e_type new_hybrid_active_band;
  sys_channel_num_type  new_hybrid_active_channel;
  cmss_misc_sub_prop_s_type *ss_misc_sub_ptr = cmss_get_misc_sub_prop_ptr(asubs_id);
  cmss_misc_gen_stack_info_s_type *ss_misc_stack1_ptr;
  cm_mm_ss_info_sub_prop_s_type *ss_sub_ptr = cmss_get_info_sub_prop(asubs_id);
  cm_mm_ss_info_gen_stack_info_s_type *ss_stack1_ptr;

  if(ss_misc_sub_ptr == NULL || ss_sub_ptr == NULL ||
      !cmutil_is_as_id_valid(asubs_id))
  {
    return;
  }
  ss_misc_stack1_ptr = ss_misc_sub_ptr->stack_info[MM_STACK_1].gen_info;
  ss_stack1_ptr = ss_sub_ptr->stack_info[MM_STACK_1].gen_info;

  if(ss_misc_stack1_ptr == NULL || ss_stack1_ptr == NULL)
  {
    return;
  }
  new_hybrid_active_band = ss_stack1_ptr->active_band;
  new_hybrid_active_channel = ss_stack1_ptr->active_channel;

  ss_misc_stack1_ptr->is_pref_srv_acq = TRUE;

  ss_misc_sub_ptr->sub_info.gpp2_sub_info.current_hdr_mcc = CM_INVALID_MOBILE_COUNTRY_CODE;

  /* Update CMSS global for HYBR_1 stack atomically */
  cmss_update_srv_status_for_stack_1(si_info_ptr->srv_status,
                                     new_hybrid_active_band,
                                     new_hybrid_active_channel,
                                     asubs_id);
}

/*===========================================================================

FUNCTION cmss_update_stack_1_lmtd_srv_ind_info

DESCRIPTION
  Update the phone object per the new service indicators.

DEPENDENCIES
  Phone object must have already been initialized with
  cmph_init().

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/

static void cmss_update_stack_1_lmtd_srv_ind_info(

  const sd_si_info_s_type   *si_info_ptr,
  /* Pointer to buffer containing new service info information */

  sys_modem_as_id_e_type     subId,

  boolean is_lmt_srv_timeout_handling

)
{
  dword                    clk_time   = time_get_uptime_secs();
  sys_srv_status_e_type prev_srv_ind = SYS_SRV_STATUS_NONE;
  cmss_s_type           *ss_ptr = cmss_ptr();

  sys_srv_status_e_type new_hdr_srv_status;
  sys_band_class_e_type new_hybrid_active_band;
  sys_channel_num_type  new_hybrid_active_channel;
  sys_time_info_s_type *time_info        = SS_CDMA_TIME_PTR(ss_ptr, subId);
  uint8                    stk_id_main = MM_STACK_0;
  uint8                    stk_id = MM_STACK_1;
#ifdef FEATURE_HICPS_STACK_SYNC_UP
  mm_sub_stk_id_s_type     stk0_mm_id = cmph_map_sub_stk_to_id(subId, MM_STACK_0);
#endif
  cm_mm_ss_info_sub_prop_s_type *ss_sub_ptr = cmss_get_info_sub_prop(subId);
  cm_mm_ss_info_gen_stack_info_s_type *ss_stack0_ptr, *ss_stack1_ptr;
  cm_mm_ss_info_3gpp2_stack_info_s_type *ss_stack1_gpp2_ptr;
  cmss_misc_sub_prop_s_type *ss_misc_sub_ptr = cmss_get_misc_sub_prop_ptr(subId);
  cmss_misc_gen_stack_info_s_type *ss_misc_stack1_ptr;

  if (!cmutil_is_as_id_valid(subId) || ss_sub_ptr == NULL)
  {
    return ;
  }
  ss_stack0_ptr = ss_sub_ptr->stack_info[MM_STACK_0].gen_info;
  ss_stack1_ptr = ss_sub_ptr->stack_info[MM_STACK_1].gen_info;
  ss_stack1_gpp2_ptr = ss_sub_ptr->stack_info[MM_STACK_1].gpp2_info;
  ss_misc_stack1_ptr = ss_misc_sub_ptr->stack_info[MM_STACK_1].gen_info;
  if(ss_stack0_ptr == NULL || ss_stack1_ptr == NULL ||
      ss_stack1_gpp2_ptr == NULL || ss_misc_stack1_ptr == NULL)
  {
    return;
  }
  new_hdr_srv_status = ss_stack1_ptr->srv_status;
  new_hybrid_active_band = ss_stack1_ptr->active_band;
  new_hybrid_active_channel = ss_stack1_ptr->active_channel;
  prev_srv_ind = ss_ptr->new_srv_avl_info[subId].stack_info[stk_id].srv_status;

  new_hdr_srv_status = sys_intl_srv_status_to_actl_srv_status(si_info_ptr->srv_status);

  /* Copy band/channel of the current active service */
  new_hybrid_active_band = si_info_ptr->band;
  new_hybrid_active_channel = si_info_ptr->chan;

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* Update the service state.
  */
  switch( si_info_ptr->mode )
  {
    case SD_MODE_HDR:

      if( si_info_ptr->usable_status != SD_SYS_USABLE_NOT_OK )
      {
        new_hdr_srv_status = si_info_ptr->srv_status;
      }
      else
      {
        new_hdr_srv_status = SYS_SRV_STATUS_NO_SRV;
      }
      /* Update CMSS global for HYBR_1 stack atomically */
      cmss_update_srv_status_for_stack_1(new_hdr_srv_status,
                                         new_hybrid_active_band,
                                         new_hybrid_active_channel,
                                         subId);

      /* Update the roaming status.
      */
      ss_stack1_ptr->roam_status =
        (sys_roam_status_e_type) si_info_ptr->roam;

      /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

      /* Get the new system id.
      */
      cmss_map_sd_sid_to_sys_sid( si_info_ptr->mode,
                                  &ss_stack1_ptr->sys_id,
                                  &si_info_ptr->sid,
                                  subId);

      /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
      /* Update the preferred acquisition indicator.
      */
      ss_misc_stack1_ptr->is_pref_srv_acq      = si_info_ptr->is_pref_srv_acq;
      ss_stack1_ptr->sys_mode                  = si_info_ptr->mode;

      /* Update the HDR active protocol
      */
      CM_MSG_HIGH_2("cmss_update_stack_1_srv_ind: HDR Active Prot changed %d to %d",
                    ss_sub_ptr->sub_info.gpp2_sub_info.hdr_gen_info.hdr_active_prot,
                    si_info_ptr->hdr_active_prot);
      ss_sub_ptr->sub_info.gpp2_sub_info.hdr_gen_info.hdr_active_prot = si_info_ptr->hdr_active_prot;

      /* Update the HDR personality
      */
      ss_sub_ptr->sub_info.gpp2_sub_info.hdr_signal_info.hdr_personality = si_info_ptr->hdr_personality;
      ss_stack1_gpp2_ptr->is_3gpp2_custom_home= si_info_ptr->is_custom_home;
      ss_sub_ptr->sub_info.gpp2_sub_info.hdr_signal_info.latitude= si_info_ptr->mode_info.hdr.latitude;
      ss_sub_ptr->sub_info.gpp2_sub_info.hdr_signal_info.longitude= si_info_ptr->mode_info.hdr.longitude;
      ss_stack1_gpp2_ptr->gpp2_ota_mcc= si_info_ptr->mode_info.hdr.hdr_mcc;
      ss_sub_ptr->sub_info.gpp2_sub_info.hdr_signal_info.system_type= si_info_ptr->mode_info.hdr.hdr_system_type;

      CM_MSG_HIGH_4("HDR latitude : %d, longitude: %d MCC from hdr : %d, system_type: %d",
                    ss_sub_ptr->sub_info.gpp2_sub_info.hdr_signal_info.latitude,
                    ss_sub_ptr->sub_info.gpp2_sub_info.hdr_signal_info.longitude,
                    ss_stack1_gpp2_ptr->gpp2_ota_mcc,
                    ss_sub_ptr->sub_info.gpp2_sub_info.hdr_signal_info.system_type);


      if(si_info_ptr->is_stable_in_svc == TRUE)
      {
        /* If CDMA is in stack0 and time info sys mode is CDMA and do not blindly update sys mode to no_srv as HDR N/W may not give
        time info */
        if(time_info->sys_mode != SYS_SYS_MODE_CDMA)
        {
          time_info->sys_mode =  SYS_SYS_MODE_NO_SRV;
        }
        /* Update the HDR time
        */
        if(si_info_ptr->time_info.sys_mode == SYS_SYS_MODE_HDR)
        {
          time_info->sys_mode = SYS_SYS_MODE_HDR;
          time_info->time.hdr_time.lp_sec     =
          si_info_ptr->time_info.time.hdr_time.lp_sec;
          time_info->time.hdr_time.ltm_offset =
          si_info_ptr->time_info.time.hdr_time.ltm_offset;
        }
      }



#ifdef FEATURE_HICPS_STACK_SYNC_UP

      /* Since HDR is acquired, deactivate the GWL stack
      ** from dormant state
      */

      if( cmregprx_get_state(stk0_mm_id) == CMREGPRX_STATE_DORMANT
          && si_info_ptr->is_stable_in_svc == TRUE )
      {
        mmoc_cmd_deact_from_dormant( stk0_mm_id, SD_SS_MODE_PREF_GWL );
      }

#endif /* HICPS */
      break;

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
    case SD_MODE_GSM:
    case SD_MODE_WCDMA:
    case SD_MODE_TDS:
      break;

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    case SD_MODE_CDMA:
    case SD_MODE_INACT:
    case SD_MODE_MAX:
    default:
      CM_ERR_1( "sd_mode = %d", si_info_ptr->mode);
      /*lint -save -e527 Unreachable
      **     CM_ERR exits when CM_DEBUG is on
      */
      new_hdr_srv_status = SYS_SRV_STATUS_NO_SRV;
      /* Update CMSS global for HYBR_1 stack atomically */
      cmss_update_srv_status_for_stack_1(new_hdr_srv_status,
                                         new_hybrid_active_band,
                                         new_hybrid_active_channel,
                                         subId);

      /*lint -restore */
      break;

  } /* switch */

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/


  /* Update the roaming status.
  */
  ss_stack1_ptr->roam_status =
    (sys_roam_status_e_type) si_info_ptr->roam;

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* Get the new system id.
  */
  cmss_map_sd_sid_to_sys_sid( si_info_ptr->mode,
                              &ss_stack1_ptr->sys_id,
                              &si_info_ptr->sid,
                              subId);

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* Update the redirection/handoff indicator.
  */
  ss_misc_sub_ptr->sub_info.gpp2_sub_info.hdr_is_redir_or_ho = si_info_ptr->is_redir_or_ho;

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  if ( ( ss_misc_stack1_ptr->srv_inform_uptime == CMSS_INFORM_SRV_CHANGE_INTER_NONE )
       || (new_hdr_srv_status > prev_srv_ind)

       || (ss_stack0_ptr->sys_mode != ss_ptr->new_srv_avl_info[subId].stack_info[stk_id_main].sys_mode)
       || ( !cmss_sys_id_match( ss_ptr->new_srv_avl_info[subId].stack_info[stk_id_main].sys_id, ss_stack0_ptr->sys_id ) &&
            (new_hdr_srv_status == prev_srv_ind )
          )
       || is_lmt_srv_timeout_handling
       || ((new_hdr_srv_status == SYS_SRV_STATUS_SRV ) &&
           (ss_sub_ptr->sub_info.gpp2_sub_info.hdr_signal_info.hdr_personality != ss_ptr->new_srv_avl_info[subId].stack_info[stk_id].rat_mode_info.hdr_mode_info.hdr_personality) )

     )
  {

    /* uptime is CMSS_INFORM_SRV_CHANGE_INTER_NONE when srv indication
    ** transitions to SRV available from PWR_SAVE or NO_SRV. Clients need
    ** to be informed immediately of service here.
    */


    ss_misc_stack1_ptr->srv_inform_uptime   =
      clk_time + cmss_rat_srv_ind_uptimers.hdr_uptimers.srv_uptimer;


    /* srv_avail_info holds serving system parameters last
    ** reported to clients by
    ** CM_SS_EVENT_SRV_CHANGED. cmss_update_ss_bit_mask ()
    ** computes the change in
    ** parameters that need to be reported to clients.
    */
    ss_stack0_ptr->changed_fields =
      cmss_get_ss_hdr_info_change(&ss_ptr->info, &ss_ptr->new_srv_avl_info[subId], subId);

  }
  else
  {
    /* By this time hdr_srv_inform_uptime is active and serving system
    ** parameter change gets informed once in 2 secs only if there is
    ** a change in parameters.
    */
    ss_stack0_ptr->changed_fields = 0;
  }

} /* cmss_update_stack_1_lmtd_srv_ind_info */

#endif

/*===========================================================================

FUNCTION cmss_get_info_sub_prop

DESCRIPTION
  get cmss info sub property pointer

DEPENDENCIES
  none

RETURN VALUE
  cm_mm_ss_info_sub_prop_s_type

SIDE EFFECTS
  none

===========================================================================*/
cm_mm_ss_info_sub_prop_s_type *cmss_get_info_sub_prop(
  sys_modem_as_id_e_type  asubs_id
)
{
  cmss_s_type *ss_ptr = cmss_ptr();

  if(!(asubs_id >= SYS_MODEM_AS_ID_1 &&
       asubs_id < ARR_SIZE(ss_ptr->info.sub_prop) &&
       asubs_id < SYS_MODEM_AS_ID_NO_CHANGE))
  {
    CM_MSG_HIGH_1("cmss get sub prop wrong sub %d", asubs_id);
    asubs_id = SYS_MODEM_AS_ID_1;
  }
  if(ss_ptr->info.sub_prop[asubs_id] == NULL)
  {
    return NULL;
  }

  return ss_ptr->info.sub_prop[asubs_id];

}

