/*===========================================================================

FUNCTION cmss_true_srv_info_alloc

DESCRIPTION
  allocate memory of true srv info

DEPENDENCIES
  none

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
static void cmss_true_srv_info_alloc()
{

  cmss_true_info_s_type *true_info_ptr = cmss_true_info_ptr();
  uint8 i, j;


  for(i=0; i<MIN(ARR_SIZE(true_info_ptr->sub_info), cmpmprx_get_num_of_sims()); i++)
  {
    if(true_info_ptr->sub_info[i] == NULL)
    {
      true_info_ptr->sub_info[i] = (cmss_true_stack_info_s_type *)cm_mem_malloc
                                   (sizeof(cmss_true_stack_info_s_type));
    }
    for(j=0; j<MAX_STACKS; j++)
    {
      if(true_info_ptr->sub_info[i]->si_info[j] == NULL)
      {
        true_info_ptr->sub_info[i]->si_info[j] = (sd_si_info_s_type *)cm_mem_malloc
            (sizeof(sd_si_info_s_type));
      }
    }
  }

}

/*===========================================================================

FUNCTION cmss_reset_true_srv_info

DESCRIPTION
  reset memory of true srv info

DEPENDENCIES
  none

RETURN VALUE
  none

SIDE EFFECTS
  none
===========================================================================*/
static void cmss_reset_true_srv_info()
{
  cmss_true_info_s_type *true_info_ptr = cmss_true_info_ptr();
  sd_si_info_s_type   *stack_si_info;
  uint8 i, j;


  for(i=0; i<MIN(ARR_SIZE(true_info_ptr->sub_info), cmpmprx_get_num_of_sims()); i++)
  {
    if(true_info_ptr->sub_info[i] != NULL)
    {
      for(j=0; j<MAX_STACKS; j++)
      {
        if(true_info_ptr->sub_info[i]->si_info[j] != NULL)
        {
          stack_si_info = true_info_ptr->sub_info[i]->si_info[j];
          stack_si_info->srv_status = SYS_SRV_STATUS_NO_SRV;
          stack_si_info->is_pref_srv_acq = TRUE;
          stack_si_info->is_redir_or_ho = FALSE;
          stack_si_info->mode = SYS_SYS_MODE_NONE;
          stack_si_info->sys_srv_cap = SYS_SRV_CAPABILITY_NONE;
          stack_si_info->srv_domain = SYS_SRV_DOMAIN_NO_SRV;
          stack_si_info->bcmcs_srv_status = SYS_BCMCS_SRV_STATUS_NO_SRV;
          stack_si_info->cs_srv_status = SYS_SRV_STATUS_NO_SRV;
          stack_si_info->is_more_pref_gwl_avail = PRL_GWL_PREFERRED_PREF_NONE;
          stack_si_info->extend_srv_info = SYS_EXTEND_SRV_INFO_NONE;
          stack_si_info->reg_domain = SYS_REG_DOMAIN_NOT_APPLICABLE;
          stack_si_info->is_lte_scanned = FALSE;
        }
      }
    }
  }
}

