/*===========================================================================

FUNCTION cmss_reset

DESCRIPTION
  Reset mode information for stack

DEPENDENCIES
  none

RETURN VALUE
  none

SIDE EFFECTS
  none
===========================================================================*/
static void cmss_reset_mode_info(
  cm_mm_ss_info_gen_stack_info_s_type *ss_stack_ptr
)
{
  if(ss_stack_ptr == NULL)
  {
    return;
  }
  /*
  ** 3.1 Initialize SS object: mode info - GW only build
  */
#if (defined CM_GW_SUPPORTED || defined FEATURE_CM_LTE)
#if (!defined(FEATURE_MMODE_CDMA_800) && !defined(FEATURE_MMODE_CDMA_1900))
  ss_stack_ptr->mode_info.gw_info.bit_err_rate           = CMSS_BER_VALUE_NO_SIGNAL;
  ss_stack_ptr->mode_info.gw_info.sim_state              = SYS_SIM_STATE_NOT_AVAILABLE;
  ss_stack_ptr->mode_info.gw_info.plmn_forbidden         = FALSE;

  cm_ss_init_mm_information( &ss_stack_ptr->mode_info.gw_info.mm_information );
  cm_ss_init_mm_information( &ss_stack_ptr->mode_info.gw_info.prev_mm_information );

#endif /* (!defined(FEATURE_MMODE_CDMA_800) && !defined(FEATURE_MMODE_CDMA_1900)) */
#endif /* defined CM_GW_SUPPORTED || defined(FEATURE_CM_LTE)*/

  /*
  ** 3.2 Initialize SS object: mode info - CDMA only build
  */
#if (defined(FEATURE_MMODE_CDMA_800) || defined(FEATURE_MMODE_CDMA_1900))
#if ( !defined(FEATURE_WCDMA) && !defined(FEATURE_GSM) )
  ss_stack_ptr->mode_info.cdma_info.band_class      = SYS_BAND_CLASS_NONE;
  ss_stack_ptr->mode_info.cdma_info.block_or_system = SYS_BLKSYS_NONE;
  ss_stack_ptr->mode_info.cdma_info.reg_zone        = CM_SS_REG_ZONE_NONE;
  ss_stack_ptr->mode_info.cdma_info.packet_zone     = CM_SS_PACKET_ZONE_NONE;
  ss_stack_ptr->mode_info.cdma_info.bs_p_rev        = CM_SS_BS_P_REV_NONE;
  ss_stack_ptr->mode_info.cdma_info.p_rev_in_use    = CM_SS_P_REV_IN_USE_NONE;
  ss_stack_ptr->mode_info.cdma_info.is_registered   = FALSE;
  ss_stack_ptr->mode_info.cdma_info.ccs_supported   = FALSE;
  ss_stack_ptr->mode_info.cdma_info.uz_id           = CM_INVALID_UZID;
  ss_stack_ptr->mode_info.cdma_info.base_id         = 0;
  ss_stack_ptr->mode_info.cdma_info.base_lat        = 0;
  ss_stack_ptr->mode_info.cdma_info.base_long       = 0;
  ss_stack_ptr->mode_info.cdma_info.srch_win_n      = 0;
  ss_stack_ptr->mode_info.cdma_info.time_info.sys_mode = SYS_SYS_MODE_NO_SRV;
#endif /* ( !defined(FEATURE_WCDMA) && !defined(FEATURE_GSM) ) */
#endif /* (defined(FEATURE_MMODE_CDMA_800) || defined(FEATURE_MMODE_CDMA_1900)) */

  /*
  ** 3.3 Initialize SS object: mode info - MM (GW + CDMA) build
  */
#ifdef CM_GW_SUPPORTED
#if (defined(FEATURE_MMODE_CDMA_800) || defined(FEATURE_MMODE_CDMA_1900))
  (void) memset( &ss_stack_ptr->mode_info, 0, sizeof( cm_ss_info_u_type ) );
  ss_stack_ptr->mode_info.gw_info.bit_err_rate   = CMSS_BER_VALUE_NO_SIGNAL;
#endif /* (defined(FEATURE_MMODE_CDMA_800) || defined(FEATURE_MMODE_CDMA_1900)) */
#endif /* defined CM_GW_SUPPORTED */

}

