      ss_ptr->new_srv_avl_info[subId].stack_info[stk_id].rssi               = CMSS_RSSI_NO_SIGNAL;
      ss_ptr->new_srv_avl_info[subId].stack_info[stk_id].ecio               = CMSS_ECIO_VALUE_NO_SIGNAL_UMTS;
