/*===========================================================================

FUNCTION cmss_p_rev_update

DESCRIPTION
  Update protocol revision info

DEPENDENCIES
  Serving System object must have already been initialized with
  cmss_init().

RETURN VALUE
  none

SIDE EFFECTS
  if update action is  CMSS_INFO_UPDATE_A_TO_N or CMSS_INFO_UPDATE_D_TO_N
  then srv_sys_info_ptr can be set to NULL


===========================================================================*/
static void cmss_p_rev_update(
  cmss_update_act_e_type  action,
  /* update action */
  const cm_srv_sys_info_type    *srv_sys_info_ptr,
  /* serving system info pointer */
  sys_modem_as_id_e_type   asubs_id
)
{
  cm_mm_ss_info_sub_prop_s_type *ss_sub_ptr = cmss_get_info_sub_prop(asubs_id);
  cm_mm_ss_info_gen_stack_info_s_type *ss_stack_ptr;
  if(ss_sub_ptr == NULL)
  {
    return;
  }
  ss_stack_ptr = ss_sub_ptr->stack_info[MM_STACK_0].gen_info;
  if(ss_stack_ptr == NULL)
  {
    return;
  }

  CM_ASSERT(srv_sys_info_ptr != NULL);

  /* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - */

  switch(action)
  {
    case CMSS_INFO_UPDATE_N_TO_D:
    case CMSS_INFO_UPDATE_A_TO_D:
    case CMSS_INFO_UPDATE_D_TO_D:

      if( srv_sys_info_ptr->rcv_fields & CM_SS_BS_P_REV_MASK )
      {
        if(ss_stack_ptr->mode_info.cdma_info.bs_p_rev != srv_sys_info_ptr->bs_p_rev)
        {
          ss_stack_ptr->mode_info.cdma_info.bs_p_rev  = srv_sys_info_ptr->bs_p_rev;
          ss_stack_ptr->changed_fields     |= CM_SS_BS_P_REV_MASK;
        }

      }

      if( srv_sys_info_ptr->rcv_fields & CM_SS_P_REV_IN_USE_MASK )
      {

        if(ss_stack_ptr->mode_info.cdma_info.p_rev_in_use != srv_sys_info_ptr->p_rev_in_use)
        {
          ss_stack_ptr->mode_info.cdma_info.p_rev_in_use  = srv_sys_info_ptr->p_rev_in_use;
          ss_stack_ptr->changed_fields         |= CM_SS_P_REV_IN_USE_MASK;
        }

      }

#ifdef FEATURE_IS2000_REL_A_SVD
      if ( ss_stack_ptr->mode_info.cdma_info.ccs_supported != srv_sys_info_ptr->ccs_supported )
      {
        ss_stack_ptr->mode_info.cdma_info.ccs_supported = srv_sys_info_ptr->ccs_supported;
        ss_stack_ptr->changed_fields          |= CM_SS_CCS_SUPPORTED_MASK;
      }
#else
      ss_stack_ptr->mode_info.cdma_info.ccs_supported = FALSE;
#endif

      break;


    case CMSS_INFO_UPDATE_N_TO_A:
    case CMSS_INFO_UPDATE_A_TO_A:
    case CMSS_INFO_UPDATE_A_TO_N:

      break;

    case CMSS_INFO_UPDATE_D_TO_A:
    case CMSS_INFO_UPDATE_D_TO_N:

      ss_stack_ptr->mode_info.cdma_info.bs_p_rev      = CM_SS_BS_P_REV_NONE;
      ss_stack_ptr->mode_info.cdma_info.p_rev_in_use  = CM_SS_P_REV_IN_USE_NONE;
      ss_stack_ptr->changed_fields         |= CM_SS_BS_P_REV_MASK;
      ss_stack_ptr->changed_fields         |= CM_SS_P_REV_IN_USE_MASK;
      break;

    default:
      CM_ERR_0("Invalid p_rev update action");
      break;

  }

} /* cmss_p_rev_update() */

/*===========================================================================

FUNCTION cmss_info_update

DESCRIPTION
  Update serving system info

DEPENDENCIES
  Serving System object must have already been initialized with
  cmss_init().

RETURN VALUE
  none

SIDE EFFECTS
  if update action is  CMSS_INFO_UPDATE_A_TO_N or CMSS_INFO_UPDATE_D_TO_N
  then srv_sys_info_ptr can be set to NULL


===========================================================================*/
static void cmss_info_update(

  cmss_update_act_e_type  action,
  /* update action */

  const cm_srv_sys_info_type    *srv_sys_info_ptr,
  /* serving system info pointer */
  sys_modem_as_id_e_type   asubs_id
)
{
  cmss_srv_status_update( action, asubs_id );
  cmss_band_and_block_update(action, srv_sys_info_ptr, asubs_id );
  cmss_is95_sys_id_update( action, srv_sys_info_ptr, asubs_id );
  cmss_reg_zone_update( action, srv_sys_info_ptr, asubs_id );
  cmss_packet_zone_update( action, srv_sys_info_ptr, asubs_id );
  cmss_p_rev_update( action, srv_sys_info_ptr, asubs_id );

} /* cmss_info_update() */


