/*===========================================================================

FUNCTION cmss_rpt_proc

DESCRIPTION
  Process reports from the lower layers.

DEPENDENCIES
  Serving System object must have already been initialized with
  cmss_init().

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmss_rpt_proc(

  const cm_hdr_type   *rpt_ptr
  /* Pointer to LL report */
)
{
#if !(defined(CM_GW_SUPPORTED) || defined(FEATURE_CM_LTE))
  SYS_ARG_NOT_USED(rpt_ptr);
  return;

#else

  const cm_rpt_type   *cm_rpt_ptr = (cm_rpt_type *) rpt_ptr;
  /* Pointer to LL report */

  cmss_misc_sub_prop_s_type *ss_misc_sub_ptr;

  CM_ASSERT( cm_rpt_ptr != NULL );
  ss_misc_sub_ptr = cmss_get_misc_sub_prop_ptr(cm_rpt_ptr->asubs_id);
  if(ss_misc_sub_ptr == NULL)
  {
    return;
  }

#if (defined(FEATURE_WCDMA_CM_CID_UPDATE_IN_DCH) && defined (FEATURE_WCDMA))
  if ((ss_misc_sub_ptr->sub_info.gen_sub_info.dch_cell_info_flgs & CMSS_IS_DCH_CELL_INFO_REQ) &&
      (cm_rpt_ptr->hdr.cmd == CM_RRC_CELL_INFO_IND))
  {
    /* All "CM_RRC_CELL_INFO_IND" reports will be ignored while expecting "CM_RRC_DCH_CELL_INFO_CNF" */
    CM_MSG_HIGH_0("CMSS_RPT: Recv CELL_INFO_IND while waiting for CELL_INFO_CNF, so ignoring evnt");
    return;
  }
#endif

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* Do command specific processing as follows:
  ** 1. Updating appropriate phone object fields.
  ** 2. Notifying clients of event if necessary.
  */
  switch( cm_rpt_ptr->hdr.cmd )
  {
    case CM_RR_STATUS_IND:
    case CM_RRC_STATUS_IND:
    {
      sys_sys_mode_e_type sys_mode = SYS_SYS_MODE_NONE;
      multimode_stack_e_type stack_id      = MM_STACK_0;;

      if(CM_RR_STATUS_IND == cm_rpt_ptr->hdr.cmd)
      {
        sys_mode = SYS_SYS_MODE_GSM;
      }
      else
      {
        sys_mode = SYS_SYS_MODE_WCDMA;
      }

      /* Determine cm_ss */
      stack_id = cmph_determine_stk_per_rat(cm_rpt_ptr->asubs_id, sys_mode);
      CM_MSG_HIGH_3_EXT("CMSS_RPT: status_ind, sys_mode=%d, asubs_id=%d, stack=%d", 
                        sys_mode, cm_rpt_ptr->asubs_id, stack_id, (cm_rpt_ptr->asubs_id+1));
      cmss_gwl_store_rssi_info( sys_mode, (void *) &cm_rpt_ptr->cmd.signal_status, cm_rpt_ptr->asubs_id);
    }
    break;

    case CM_MM_INFORMATION_IND:
    {
      multimode_stack_e_type stack_id = MM_STACK_0;
      cm_mm_ss_info_sub_prop_s_type *ss_sub_ptr = cmss_get_info_sub_prop(cm_rpt_ptr->cmd.mm_information_ind.as_id);
      cm_mm_ss_info_gen_stack_info_s_type *ss_stack_ptr;

      if(ss_sub_ptr == NULL || !cmutil_is_as_id_valid(cm_rpt_ptr->cmd.mm_information_ind.as_id))
      {
        return;
      }
      ss_stack_ptr = ss_sub_ptr->stack_info[MM_STACK_2].gen_info;
      CM_MSG_HIGH_1("CMSS_RPT: mm_information_ind, as_id=%d", cm_rpt_ptr->cmd.mm_information_ind.as_id);

      /* Determine is_stack_id for SVLTE HYBR-2*/
      if (cmph_is_subs_feature_mode_1x_sxlte(cm_rpt_ptr->cmd.mm_information_ind.as_id))
      {
        if( ss_stack_ptr != NULL &&
            cmss_is_stack2_operational(cm_rpt_ptr->cmd.mm_information_ind.as_id) &&
            ((sys_srv_status_is_srv(ss_stack_ptr->srv_status) &&
              ss_stack_ptr->sys_mode == SYS_SYS_MODE_LTE) ||
             (cm_rpt_ptr->cmd.mm_information_ind.info.rat == SYS_RAT_LTE_RADIO_ACCESS)))
        {
          stack_id = MM_STACK_2;
        }
        else
        {
          stack_id = MM_STACK_0;
        }
      }
      else
      {
        stack_id = MM_STACK_0;
      }

      cmss_process_mm_info_ind_rpt(cmph_map_sub_stk_to_id(cm_rpt_ptr->cmd.mm_information_ind.as_id,stack_id),
                                   cm_rpt_ptr->cmd.mm_information_ind.info );

      break;
    }

    case CM_SIM_STATE_CHGD_F:
      cmss_process_sim_state_chgd_rpt(  cm_rpt_ptr );
      break;

    case CM_DATA_SUSPEND_CHGD_F:
	{
      /* If  LTE service is in main stack,
           ** update hybr_2(LTE) stack info if LTE has service.
      */
	  cmss_misc_sub_prop_s_type *ss_intl_info_ps_sub_prop_ptr = cmss_get_misc_sub_prop_ptr(cm_rpt_ptr->asubs_id);
#ifdef FEATURE_CM_DEBUG_BUFFER
      cmdbg_add_to_dbg_buffer(CM_BUFF_RPT_TYPE, CM_DATA_SUSPEND_CHGD_F, (void *)cm_rpt_ptr);
#endif
	  if(ss_intl_info_ps_sub_prop_ptr !=  NULL && (!(ss_intl_info_ps_sub_prop_ptr->sub_info.gen_sub_info.ue_init_ps_data_suspend)))
	  {
             cmss_process_data_suspend_rpt( cm_rpt_ptr->cmd.data_suspend_chgd.data_suspend,
                                     cmph_map_sub_stk_to_id(cm_rpt_ptr->asubs_id, cm_rpt_ptr->cmd.data_suspend_chgd.stack_id));
	  }
      break;
	}
    case CM_CIPHER_IND:
      cmss_process_cipher_ind_rpt(cm_rpt_ptr->cmd.cipher_ind);
      break;

    case CM_EMERGENCY_NUM_LIST_IND:
      cmss_process_emerg_num_list_ind_rpt (cm_rpt_ptr);
      break;

    case CM_CELL_SERVICES_IND:
      cmss_process_cell_supp_services_rpt (cm_rpt_ptr);
      break;

    case CM_HSPA_CALL_STATUS_IND:
      cmss_process_hspa_call_status_rpt (cm_rpt_ptr);
      break;

    case CM_CONN_MODE_SERVICE_STATUS_IND:
      cmss_process_conn_mode_service_status_rpt(cm_rpt_ptr);
      break;

    case CM_RR_CELL_INFO_IND:
      cmss_process_cell_info_rpt(cm_rpt_ptr,SYS_SYS_MODE_GSM);
      break;

#if (defined(FEATURE_WCDMA_CM_CID_UPDATE_IN_DCH) &&  defined(FEATURE_WCDMA))
    case CM_RRC_DCH_CELL_INFO_CNF:
#endif
    case CM_RRC_CELL_INFO_IND:
      cmss_process_cell_info_rpt(cm_rpt_ptr,SYS_SYS_MODE_WCDMA);
      break;

    case CM_REG_REJECT_IND:
      cmss_process_reg_reject_ind_rpt(cm_rpt_ptr);
      break;

    case CM_GAN_INFO_IND:
      cmss_process_gan_info_rpt(cm_rpt_ptr);
      break;

    case CM_CELL_ACCESS_IND:
      cmss_update_cell_access_ind(cm_rpt_ptr);
      break;

    case CM_RR_CELL_BROADCAST_INFO_IND:
    case CM_RRC_CELL_BROADCAST_INFO_IND:
      cmss_process_cb_info_rpt(cm_rpt_ptr);
      break;
    case CM_HOME_NODEB_NAME_IND:
      cmss_update_home_nodeb_name_ind(cm_rpt_ptr);
      break;
    default:
      break;

  } /* switch( cm_rpt_ptr->hdr.cmd ) */

#endif
} /* cmss_rpt_proc() */

/*===========================================================================

FUNCTION cmss_generic_rpt_proc

DESCRIPTION
  Process Generic reports in CMSS


DEPENDENCIES
  Serving System object must have already been initialized with
  cmss_init().

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void cmss_generic_rpt_proc(

  const cm_hdr_type   *rpt_ptr
  /* Pointer to generic reports */
)
{
  const cm_generic_rpt_s_type              *gen_rpt_ptr = (cm_generic_rpt_s_type *)rpt_ptr;

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  CM_ASSERT( gen_rpt_ptr != NULL );

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  switch(gen_rpt_ptr->hdr.cmd)
  {
    case CM_MMGSDI_CARD_RPT:
      switch(gen_rpt_ptr->generic_rpt.mmgsdi_card_rpt.evt)
      {
        case MMGSDI_SUBSCRIPTION_READY_EVT:
        {
          cm_mmgsdi_session_id_table_entry_s_type  *ssn_entry = NULL;
          sys_modem_as_id_e_type                    asubs_id = SYS_MODEM_AS_ID_1;
          ssn_entry = cm_mmgsdi_ssn_tbl_get_entry_by_id(gen_rpt_ptr->generic_rpt.mmgsdi_card_rpt.session_id);

          if(ssn_entry != NULL)
          {
            asubs_id = SESSION_TO_AS_ID(ssn_entry->session_type);
          }
          cmss_update_home_mcc(asubs_id);
          break;
        }

        default:
          break;

      }
      break;

    case CM_SOA_MSG_MCC:
      /* Store the hdr mcc received, in local buffer**/
      if (gen_rpt_ptr->hdr.asubs_id == cmmsc_get_1x_sub() &&
          ((gen_rpt_ptr->generic_rpt.mcc_msg.stack_id == MM_STACK_1) ||
           (gen_rpt_ptr->generic_rpt.mcc_msg.stack_id == MM_STACK_0)))
      {
        if(cmss_get_misc_sub_prop_ptr(gen_rpt_ptr->hdr.asubs_id) != NULL)
        {
          cmss_get_misc_sub_prop_ptr(gen_rpt_ptr->hdr.asubs_id)->sub_info.gpp2_sub_info.current_hdr_mcc =
            (cm_country_code_type)gen_rpt_ptr->generic_rpt.mcc_msg.mcc;
        }
      }
      break;

    default:
      break;
  }
} /* cmss_generic_rpt_proc */


/*===========================================================================

FUNCTION cmss_proc_call_connected

DESCRIPTION
  This function should be called when the call enters conversation.

DEPENDENCIES
  cmssidm_init() should have been called previously.

RETURN VALUE
  None.

SIDE EFFECTS
  None.
===========================================================================*/
void                           cmss_proc_call_connected
(
  const cmcall_s_type                  *call_ptr
  /* Pointer to call object which entered conversation.
  */
)
/*lint -esym(714,cmss_proc_call_connected) */
/*lint -esym(765,cmss_proc_call_connected)
** Can't be static, used by cmxcall.c, can't externalize through cmss.h as then we
** run into circular header inclusion between cmxcall.c and cmss.h
*/
/*lint -esym(715,call_ptr)*/
{
  /* Pointer to serving system object.
  */

#ifdef FEATURE_HDR_HANDOFF
  sys_sys_mode_e_type      prev_idm = cmssidm_get_curr_idm(call_ptr->mm_id.asubs_id);
  cm_mm_ss_info_sub_prop_s_type *ss_sub_ptr = cmss_get_info_sub_prop(call_ptr->mm_id.asubs_id);
  cm_mm_ss_info_gen_stack_info_s_type *ss_stack_ptr;

  if(ss_sub_ptr == NULL)
  {
    return;
  }
  ss_stack_ptr = ss_sub_ptr->stack_info[MM_STACK_0].gen_info;
  if(ss_stack_ptr ==NULL)
  {
    return;
  }
  ss_stack_ptr->changed_fields = 0;

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* Process the call connected event report.
  */
  cmssidm_proc_call_connected( call_ptr );

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* If IDM changed, notify CM clients of the corresponding event.
  */
  if ( cmssidm_get_curr_idm(call_ptr->mm_id.asubs_id) != prev_idm )
  {
    ss_stack_ptr->changed_fields        |= CM_SS_IDLE_DIGITAL_MODE_MASK;
    ss_sub_ptr->sub_info.gpp2_sub_info.cur_idle_digital_mode  = cmssidm_get_curr_idm(call_ptr->mm_id.asubs_id);
    ss_sub_ptr->sub_info.gpp2_sub_info.prev_idle_digital_mode = cmssidm_get_prev_idm(call_ptr->mm_id.asubs_id);
    cmss_event( cmph_map_sub_stk_to_id(call_ptr->mm_id.asubs_id, MM_STACK_0), CM_SS_EVENT_SRV_CHANGED );

  }
#endif // FEATURE_HDR_HANDOFF


} /* cmss_proc_call_connected */
/*lint +esym(715,call_ptr)*/


/*===========================================================================

FUNCTION cmss_proc_call_ended

DESCRIPTION
  This function should be called to process the call end event from
  CMCALL.

DEPENDENCIES
  cmssidm_init() should have been called previously.

RETURN VALUE
  None.

SIDE EFFECTS
  None.
===========================================================================*/
void                           cmss_proc_call_ended
(
  sys_modem_as_id_e_type  asubs_id
)
{

#ifdef FEATURE_HDR_HANDOFF
  /* Pointer to serving system object.
  */
  sys_sys_mode_e_type      prev_idm = cmssidm_get_curr_idm(asubs_id);
  cm_mm_ss_info_sub_prop_s_type *ss_sub_ptr = cmss_get_info_sub_prop(asubs_id);
  cm_mm_ss_info_gen_stack_info_s_type *ss_stack_ptr;

  if(ss_sub_ptr == NULL)
  {
    return;
  }
  ss_stack_ptr = ss_sub_ptr->stack_info[MM_STACK_0].gen_info;
  if(ss_stack_ptr ==NULL)
  {
    return;
  }

  /* Process the call ended event report.
  */
  ss_stack_ptr->changed_fields = 0;
  cmssidm_proc_call_ended(asubs_id);

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* If IDM changed, notify CM clients of the corresponding event.
  */
  if ( cmssidm_get_curr_idm(asubs_id) != prev_idm )
  {
    ss_stack_ptr->changed_fields |= CM_SS_IDLE_DIGITAL_MODE_MASK;
    ss_sub_ptr->sub_info.gpp2_sub_info.cur_idle_digital_mode = cmssidm_get_curr_idm(asubs_id);
    ss_sub_ptr->sub_info.gpp2_sub_info.prev_idle_digital_mode = cmssidm_get_prev_idm(asubs_id);
  }

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* Generate IDM event if changed_fields is not zero.
  */
  if ( ss_stack_ptr->changed_fields != 0 )
  {
    /* Inform the clients that the serving system was modified.
    */
    cmss_event( cmph_map_sub_stk_to_id(asubs_id, MM_STACK_0), CM_SS_EVENT_SRV_CHANGED );
  }
#endif // FEATURE_HDR_HANDOFF
}

/*===========================================================================

FUNCTION cmss_proc_full_srv_lost

DESCRIPTION
   Process the service indication from SD/RRC.


DEPENDENCIES
  Serving System object must have already been initialized with
  cmss_init().

RETURN VALUE
  none

SIDE EFFECTS
  none

===========================================================================*/
void                           cmss_proc_full_srv_lost
(
  mm_sub_stk_id_s_type   mm_id
)
{

  cmph_s_type *ph_ptr = cmph_ptr();
  sd_ss_band_pref_e_type band_3gpp   = (SD_MODE_CONTAIN (ph_ptr->device_prop.hw_capability.mode_capability, SD_SS_MODE_PREF_GSM) |
                                        SD_MODE_CONTAIN (ph_ptr->device_prop.hw_capability.mode_capability, SD_SS_MODE_PREF_WCDMA));
  sd_ss_band_pref_e_type band_3gpp2 =
    (SD_MODE_CONTAIN (ph_ptr->device_prop.hw_capability.mode_capability, SD_SS_MODE_PREF_CDMA) |
     SD_MODE_CONTAIN (ph_ptr->device_prop.hw_capability.mode_capability, SD_SS_MODE_PREF_HDR) );
  cm_network_sel_mode_pref_e_type int_net_sel_mode = CM_NETWORK_SEL_MODE_PREF_AUTOMATIC;
  cm_mm_ss_info_sub_prop_s_type *ss_sub_ptr = cmss_get_info_sub_prop(mm_id.asubs_id);
  cm_mm_ss_info_gen_stack_info_s_type *ss_stack1_ptr, *ss_stack2_ptr;
  cmph_sub_info_s_type              *ph_sub_ptr = cmph_get_sub_ptr(mm_id.asubs_id);

  if(ss_sub_ptr == NULL|| ph_sub_ptr == NULL || !cmutil_is_as_id_valid(mm_id.asubs_id))
  {
    return;
  }

  ss_stack1_ptr = ss_sub_ptr->stack_info[MM_STACK_1].gen_info;
  ss_stack2_ptr = ss_sub_ptr->stack_info[MM_STACK_2].gen_info;

  /* Report full service lost to Policy Manager */
  if(mm_id.stk_id == MM_STACK_1)
  {
    is_stack1_full_srv_lost[mm_id.asubs_id] = TRUE;
  }
  else if(mm_id.stk_id == MM_STACK_2)
  {
    is_stack2_full_srv_lost[mm_id.asubs_id] = TRUE;
  }

  if((mm_id.stk_id == MM_STACK_1 || mm_id.stk_id == MM_STACK_2) &&
      (cmph_is_subs_feature_mode_svlte(mm_id.asubs_id) ||
       cmph_is_subs_feature_mode_srlte(mm_id.asubs_id)) &&
      !((cmss_is_stack1_operational(mm_id.asubs_id) &&
         !cmss_is_stack2_operational(mm_id.asubs_id) &&
         is_stack1_full_srv_lost[mm_id.asubs_id])
        ||
        (!cmss_is_stack1_operational(mm_id.asubs_id) &&
         cmss_is_stack2_operational(mm_id.asubs_id) &&
         is_stack2_full_srv_lost[mm_id.asubs_id])
        ||
        (cmss_is_stack1_operational(mm_id.asubs_id) &&
         cmss_is_stack2_operational(mm_id.asubs_id) &&
         is_stack1_full_srv_lost[mm_id.asubs_id] && is_stack2_full_srv_lost[mm_id.asubs_id]))
    )
  {
    /* In SxLTE on Sub1, do not send full service lost to PM for
    ** second stack until all operational hybrid stacks have scanned
    ** and indicated full service lost
    */
    CM_MSG_HIGH_4("full_srv_lost: in SxLTE, sub %d, stack=%d, stk1 %d, stk2 %d",
                     mm_id.asubs_id,
                     mm_id.stk_id, 
                     is_stack1_full_srv_lost[mm_id.asubs_id], 
                     is_stack2_full_srv_lost[mm_id.asubs_id]);
  }
  else if(mm_id.stk_id == MM_STACK_0)
  {
    /* Don't report acq_fail to PM while the UE is in a CS call so PM does not enter full rat.
    */
    if((cmcall_find_active_cs_call_per_sub(mm_id.asubs_id) == CM_CALL_ID_INVALID) &&
       (!cmsds_is_ext_volte_call_active_per_sub(mm_id.asubs_id)) &&
       (!cmph_is_in_emergency_cb())
      )
    {
      cmpmprx_report_full_srv_lost(
        mm_id.asubs_id,
        (sys_modem_stack_id_e_type)mm_id.stk_id);
    }
    else
    {
      CM_MSG_HIGH_1("full_srv_lost: skip sending ACQ_FAIL to PM, sub %d", mm_id.asubs_id);
    }
  }
  else
  {
    cmpmprx_report_full_srv_lost(
      mm_id.asubs_id,
      (sys_modem_stack_id_e_type)mm_id.stk_id);
  }

  return;

} /* cmss_proc_full_srv_lost */

#ifdef FEATURE_CALL_THROTTLE

/*===========================================================================

FUNCTION cmss_orig_thr_add_table_enrty

DESCRIPTION
  This function adds a new entry to the origination throttle table

DEPENDENCIES
  cmss_init() should have been called previously.

RETURN VALUE
The throttle status of the added entry

SIDE EFFECTS
  None.
===========================================================================*/
static boolean cmss_orig_thr_add_tbl_entry
(

  cmss_orig_thr_table_s_type *thr_tbl_ptr,
  /* Pointer to the origination throttle table
  */

  cm_ss_orig_thr_call_status_s_type *thr_call_status,
  /* Information about the current call status
  */

  sys_modem_as_id_e_type   asubs_id
)
{

  boolean is_throttled   = FALSE;
  dword min_adj_time     = (dword) (-1);
  dword curr_adj_time    = 0;
  int q_counter = 0;
  cmss_misc_sub_prop_s_type *ss_misc_sub_ptr = cmss_get_misc_sub_prop_ptr(asubs_id);

  cmss_orig_thr_table_q_type  *q_new_item_ptr = NULL;
  cmss_orig_thr_table_q_type  *q_item_ptr = NULL;
  cmss_orig_thr_table_q_type  *q_temp_item_ptr = NULL;

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
  if(thr_tbl_ptr == NULL || thr_call_status == NULL)
  {
    sys_err_fatal_null_ptr_exception();
    return FALSE;
  }
  if(ss_misc_sub_ptr == NULL)
  {
    return FALSE;
  }

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* Check if there is a empty slot in the orig throttle table
  */
  q_counter = q_cnt(&(thr_tbl_ptr->cmss_orig_thr_q ));

  if(thr_tbl_ptr->num_valid_entries < CMSS_ORIG_THR_TABLE_MAX_ENTRIES)
  {
    /* Add this entry in the orig throttle table
       */
    q_new_item_ptr = (cmss_orig_thr_table_q_type *)cm_mem_malloc( sizeof(cmss_orig_thr_table_q_type));
    (void) q_link( q_new_item_ptr, &q_new_item_ptr->link );  /* init link */

    is_throttled = cmss_orig_thr_tbl_entry_info_put(
                     &(q_new_item_ptr->cmss_orig_thr_tbl),
                     thr_call_status,
                     asubs_id);
    thr_tbl_ptr->num_valid_entries++;

    // check if this is the first entry into queue
    if ( q_counter == 0 )
    {
      q_put( &(thr_tbl_ptr->cmss_orig_thr_q), &q_new_item_ptr->link);
    }
    else
    {
      /* Insert the new system at the beginning of the queue*/
#ifdef FEATURE_Q_NO_SELF_QPTR
      q_insert( &(thr_tbl_ptr->cmss_orig_thr_q),
                & q_new_item_ptr->link,
                & ((cmss_orig_thr_table_q_type *) q_check( &(thr_tbl_ptr->cmss_orig_thr_q) ))->link );
#else
      q_insert( & q_new_item_ptr->link,
                & ((cmss_orig_thr_table_q_type *) q_check( &(thr_tbl_ptr->cmss_orig_thr_q) ))->link );

#endif /* FEATURE_Q_NO_SELF_QPTR */
    }

    CM_MSG_HIGH_2(" Added new entry to Orig. Thr. Tbl. Slots avail. %d. Added bc 0x%x",
                  thr_tbl_ptr->num_valid_entries,
                  thr_call_status->mode_info.cdma_info.band_class);

    sd_misc_sys_id_print( thr_call_status->sys_id );

    return is_throttled ;

  }

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* If we got here, we need to remove the oldest entry in the orig throttle
  ** table and add this item into Q
  */

  if(  q_counter  > 0)
  {
    q_item_ptr = q_check(&(thr_tbl_ptr->cmss_orig_thr_q));
    if( NULL == q_item_ptr )
    {
      sys_err_fatal_null_ptr_exception();
    }
  }

  for(; (q_counter > 0) && (q_item_ptr != NULL); q_counter--)
  {
    if(cmss_is_hard_failure_throttle_reason (
          q_item_ptr->cmss_orig_thr_tbl.orig_call_info.call_status))

    {
      curr_adj_time = q_item_ptr->cmss_orig_thr_tbl.thr_uptime -
                      ss_misc_sub_ptr->sub_info.gen_sub_info.hard_fail_thr_period;
    }
    else
    {
      curr_adj_time = q_item_ptr->cmss_orig_thr_tbl.thr_uptime -
                      thr_time[q_item_ptr->cmss_orig_thr_tbl.idx];

      CM_ASSERT( q_item_ptr->cmss_orig_thr_tbl.thr_uptime >=
                 thr_time[q_item_ptr->cmss_orig_thr_tbl.idx] );
    }

    if( curr_adj_time < min_adj_time )
    {
      min_adj_time = curr_adj_time;
      //ins_pos      = i;
      q_temp_item_ptr = q_item_ptr;
    }
    q_item_ptr = q_next(&(thr_tbl_ptr->cmss_orig_thr_q), &(q_item_ptr->link));
  }

  if(q_temp_item_ptr != NULL)
  {
    sd_misc_sys_id_print(
      q_temp_item_ptr->cmss_orig_thr_tbl.orig_call_info.sys_id );
#ifdef FEATURE_Q_NO_SELF_QPTR
    q_delete( &(thr_tbl_ptr->cmss_orig_thr_q), &q_temp_item_ptr->link );
#else
    q_delete( &q_temp_item_ptr->link );
#endif

    (void) memset( &q_temp_item_ptr->cmss_orig_thr_tbl.orig_call_info.mode_info, 0,
                   sizeof( cm_ss_orig_thr_ss_info_u_type ));

    cm_mem_free(q_temp_item_ptr);
    CM_MSG_HIGH_0( "Deleted entry from Orig. Thr. Tbl.");

  }
  /* Add this entry in the orig throttle table
  */
  q_new_item_ptr = (cmss_orig_thr_table_q_type *)cm_mem_malloc( sizeof(cmss_orig_thr_table_q_type));
  (void) q_link( q_new_item_ptr, &q_new_item_ptr->link );  /* init link */

  is_throttled = cmss_orig_thr_tbl_entry_info_put(
                   &(q_new_item_ptr->cmss_orig_thr_tbl),
                   thr_call_status,
                   asubs_id);

  q_counter = q_cnt(&(thr_tbl_ptr->cmss_orig_thr_q ));
  // check if this is the first entry into queue
  if ( q_counter == 0 )
  {
    q_put( &(thr_tbl_ptr->cmss_orig_thr_q), &q_new_item_ptr->link);
  }
  else
  {
    /* Insert the new system at the beginning of the queue*/
#ifdef FEATURE_Q_NO_SELF_QPTR
    q_insert( &(thr_tbl_ptr->cmss_orig_thr_q),
              & q_new_item_ptr->link,
              & ((cmss_orig_thr_table_q_type *) q_check( &(thr_tbl_ptr->cmss_orig_thr_q) ))->link );
#else
    q_insert( & q_new_item_ptr->link,
              & ((cmss_orig_thr_table_q_type *) q_check( &(thr_tbl_ptr->cmss_orig_thr_q) ))->link );

#endif /* FEATURE_Q_NO_SELF_QPTR */
  }

  return is_throttled ;

} /* cmss_orig_thr_add_tbl_entry */



/*===========================================================================

FUNCTION cmss_orig_thr_update_tbl_entry

DESCRIPTION
  This function should be called to update a particular origination throttle
  table with the call status

DEPENDENCIES
  cmss_init() should have been called previously.

RETURN VALUE
  The throttle status of the updated entry.

SIDE EFFECTS
  None.
===========================================================================*/

static boolean cmss_orig_thr_update_tbl_entry(

  cmss_orig_thr_table_entry_s_type *tbl_entry_ptr,
  /* The pointer to the particular table entry
  */

  const cm_ss_orig_thr_call_status_s_type *thr_call_status,
  /* The throttle status of the call
  */

  sys_modem_as_id_e_type  asubs_id
)
{
  cmph_s_type  *ph_ptr = cmph_ptr();
  dword        uptime  = time_get_uptime_secs();
  unsigned int r_value = 0;
  unsigned int accolc  = 0;
  cmss_misc_sub_prop_s_type *ss_misc_sub_ptr = cmss_get_misc_sub_prop_ptr(asubs_id);

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
  CM_ASSERT( tbl_entry_ptr != NULL );
  CM_ASSERT( ph_ptr != NULL );
  CM_ASSERT( thr_call_status != NULL );
  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
  if(ss_misc_sub_ptr == NULL || !cmutil_is_as_id_valid(asubs_id) ||
      !IS_VALID_PH_SUB_PTR(asubs_id))
  {
    return FALSE;
  }

  /* Update the table entry with the new throttle status
  */
  tbl_entry_ptr->orig_call_info.call_status = thr_call_status->call_status;
  tbl_entry_ptr->orig_call_info.call_type   = thr_call_status->call_type;
  tbl_entry_ptr->orig_call_info.sys_id      = thr_call_status->sys_id;
  tbl_entry_ptr->orig_call_info.mode_info   = thr_call_status->mode_info;

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
  /* If the throttle reason is a hard failure , use fixed time throttling
  */
  if(cmss_is_hard_failure_throttle_reason(thr_call_status->call_status))
  {
    tbl_entry_ptr->thr_uptime = uptime + ss_misc_sub_ptr->sub_info.gen_sub_info.hard_fail_thr_period;
  }
  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* If the throttle reason is not a hard failure , use telescopic throttling
  ** which is determined by the thr_time[idx]. For non jcdma, when the system
  ** has been throttled  cmss_orig_thr_max_timer times, any further
  ** throttling causes the throttle time to be set to the maximum value (15 mins)
  ** For JCDMA , the counter is reset once this happens.
  */
  else
  {
    if(tbl_entry_ptr->idx < cmss_orig_thr_max_timer - 1)
    {
      tbl_entry_ptr->idx++;
    }
    else if(cm_is_jcdma_enable())
    {
      /* Restart the counter to 1.
      */
      tbl_entry_ptr->idx = 1;
    }

    tbl_entry_ptr->thr_uptime                 = time_get_uptime_secs() +
        thr_time[tbl_entry_ptr->idx];

    CM_MSG_MED_2("Orig Thr Tbl idx=%d, cmss_orig_thr_max_timer=%d",tbl_entry_ptr->idx,cmss_orig_thr_max_timer);

    /* Check if we are starting the timer, if we are then randomize the
    ** backoff time
    */
    if( (tbl_entry_ptr->idx > 0) && (thr_time[tbl_entry_ptr->idx - 1] == 0) &&
        (thr_time[tbl_entry_ptr->idx] !=0) && ((int) ph_ptr->sub_info[asubs_id]->accolc < 10) )
    {
      /*Get r_value */
      accolc = (unsigned int)(ph_ptr->sub_info[asubs_id]->accolc * CMSS_ORIG_THR_RND_INT *1000);
      r_value = ROUNDOFF(accolc, 1000);

      tbl_entry_ptr->thr_uptime+= r_value;
    }
  }
  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  CM_MSG_HIGH_2( "Orig. Thr. Tbl. updated thr uptime %d uptime %d",
                 tbl_entry_ptr->thr_uptime,
                 time_get_uptime_secs());
  sd_misc_sys_id_print( tbl_entry_ptr->orig_call_info.sys_id );

  if(  tbl_entry_ptr->thr_uptime > uptime)
  {
    return TRUE;
  }

  return FALSE;
} /* cmss_orig_thr_update_tbl_entry */


/*===========================================================================

FUNCTION cmss_is_orig_successful

DESCRIPTION
  This function checks if the throttle reason given is one of the reasons for
  call success

DEPENDENCIES
  None.

RETURN VALUE
  TRUE  is the call was successful
  FALSE otherwise

SIDE EFFECTS
  None.
===========================================================================*/

static boolean cmss_is_orig_successful(
  cm_ss_orig_thr_reasons_e_type thr_reason
  /* The end reason
  */
)
{
  switch(thr_reason)
  {

    case CM_SS_ORIG_THR_DS_MIP_UP_SUCCESS:
    /* MIP Success
    */
    case CM_SS_ORIG_THR_DS_PPP_UP_SUCCESS:
    /* PPP Success
    */
    case CM_SS_ORIG_THR_DS_V6_SUCCESS:
      /* IPv6 setup Success
      */
      return TRUE;

    default:
      return FALSE;
  }
}


/*===========================================================================

FUNCTION cmss_orig_thr_update_tbl_entry_with_call_status

DESCRIPTION
  This function should be called to update the origination throttle table
  with the call status

DEPENDENCIES
  cmss_init() should have been called previously.

RETURN VALUE
  The throttle status of the added/modified entry.

SIDE EFFECTS
  None.
===========================================================================*/
boolean cmss_orig_thr_update_tbl_entry_with_call_status
(
  cmss_orig_thr_table_s_type *thr_tbl_ptr,
  /* Pointer to the origination throttle table
  */
  cm_ss_orig_thr_call_status_s_type *thr_call_status,
  /* Information about the current call status
  */
  sys_modem_as_id_e_type  asubs_id
)
/*lint -esym(818, thr_call_status)
*/
{
  boolean       is_throttled           = FALSE;

  cmss_orig_thr_table_q_type *thr_tbl_entry_ptr;

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
  if(thr_tbl_ptr == NULL || thr_call_status == NULL)
  {
    sys_err_fatal_null_ptr_exception();
    return FALSE;
  }

  thr_tbl_entry_ptr = cmss_orig_thr_get_orig_tbl_entry(
                        thr_tbl_ptr,
                        thr_call_status->sys_id,
                        thr_call_status->mode_info.cdma_info.band_class,
                        thr_call_status->mode_info.cdma_info.packet_zone );

  if( thr_tbl_entry_ptr != NULL )
  {
    if( cmss_is_orig_successful(thr_call_status->call_status) )
    {
      /* Reset the entry as the call was succesful
      */
      CM_MSG_HIGH_0( "Reseting Orig. Thr. Tbl. entry");
      sd_misc_sys_id_print( thr_tbl_entry_ptr->cmss_orig_thr_tbl.orig_call_info.sys_id );
      cmss_orig_thr_reset_tbl_entry( thr_tbl_ptr, thr_tbl_entry_ptr );
      thr_tbl_entry_ptr = NULL;
      if (thr_tbl_ptr->num_valid_entries)
      {
        thr_tbl_ptr->num_valid_entries--;
      }

    } /* cmss_is_orig_successful */
    else
    {

      /* Calls are not throttled if uptime >= Thrttl time, so CM-clients
      ** may need to update Thrttl tbl. so allow the update, else
      ** ignore.
      */
      if( time_get_uptime_secs() >= thr_tbl_entry_ptr->cmss_orig_thr_tbl.thr_uptime )
      {
        is_throttled = cmss_orig_thr_update_tbl_entry(
                         &(thr_tbl_entry_ptr->cmss_orig_thr_tbl), thr_call_status, asubs_id );
      }
      else
      {
        /* We should never get here.
        */
        CM_MSG_HIGH_0("curr sys not throttled, no need to update tbl");
        CM_ASSERT( FALSE );
      }

    } /* else cmss_is_call_successful */

  } /* if( thr_tbl_entry_ptr != NULL ) */
  else
  {
    /* We did not find a match for the SID/PZID in the table, add a new
    ** entry. If we need to add new throttling information, add this entry
    **  in the origination throttle table.
    */
    if( !cmss_is_orig_successful( thr_call_status->call_status ))
    {
      is_throttled = cmss_orig_thr_add_tbl_entry( thr_tbl_ptr, thr_call_status, asubs_id );
    }

    /* Else, return FALSE
    */
    else
    {
      CM_MSG_HIGH_0("Orig. Thr. Tbl. Entry not found");
      sd_misc_sys_id_print( thr_call_status->sys_id );

      return FALSE;
    }
  }/* else if( thr_tbl_entry_ptr != NULL ) */

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* We either added a new entry or modified an existing entry, so need to
  ** report this to the clients
  */
  cmss_event( cmph_map_sub_stk_to_id(asubs_id, MM_STACK_0), CM_SS_EVENT_ORIG_THR_TBL_UPDATE );

  /* If throttle status changed, informed clients.
  */
  cmss_misc_set_ss_info_thr_status(asubs_id);

  return ( is_throttled );

}/* cmss_orig_thr_update_tbl_with_call_status */
/*lint +esym(818, thr_call_status)
*/

/*===========================================================================

FUNCTION cmss_map_call_end_status_thr_status

DESCRIPTION
  This function maps the call_end status to the throttle status

DEPENDENCIES
  cmss_init() should have been called previously.

RETURN VALUE
  Throttle reason.

SIDE EFFECTS
  None.
===========================================================================*/
static cm_ss_orig_thr_reasons_e_type cmss_map_call_end_status_to_thr_status
(
  cm_call_end_e_type call_end_status
  /* The call end reason
  */
)
{
  switch(call_end_status)
  {
    /* Received Intercept from BS
    */
    case CM_CALL_END_INTERCEPT:
      return( CM_SS_ORIG_THR_CM_INTERCEPT );

    /* SO Reject
    */
    case CM_CALL_END_REL_SO_REJ:
      return( CM_SS_ORIG_THR_CM_REL_SO_REJ );

    default:
      return( CM_SS_ORIG_THR_REASON_NONE );

  } /* switch */
} /* cmss_map_call_end_status_to_thr_status */


/*===========================================================================

FUNCTION cmss_check_if_orig_thr_end_status

DESCRIPTION
  This function checks is the origination needs to be throttled due to
  indication from lower layers

DEPENDENCIES
  cmss_init() should have been called previously.

RETURN VALUE
  True if end status needs to be throttled
  False otherwise.

SIDE EFFECTS
  None.
===========================================================================*/

static boolean cmss_check_if_orig_thr_end_status(
  cm_call_end_e_type end_status
  /* Call end reason
  */
)
{
  switch(end_status)
  {
    case CM_CALL_END_INTERCEPT:
    case CM_CALL_END_REL_SO_REJ:
      return TRUE;
    /* Return true for all the above cases
    */
    default:
      return FALSE;
  } /* switch (end_status) */
}/* cmss_check_if_orig_thr_end_status */


/*===========================================================================

FUNCTION cmss_check_if_orig_thr_true

DESCRIPTION
  This function checks is the origination needs to be throttled

DEPENDENCIES
  cmss_init() should have been called previously.

RETURN VALUE
  True if the origination needs to be throttled
  False otherwise.

SIDE EFFECTS
  None.
===========================================================================*/
boolean cmss_check_if_orig_thr_true
(
  sys_sys_id_s_type           sys_id,
  /* The sys id of the system, SID,NID/PZID
  */

  sys_band_class_e_type       band_class,
  /* The band class information
  */

  cmss_orig_thr_table_s_type *thr_tbl_ptr,
  /* Origination throttle table pointer
  */

  cm_call_type_e_type         call_type,
  /* Call type - VOICE, SMS, E911, etc
  */

  uint16                      packet_zone
  /* The packet zone id
  */

)
{

  dword uptime = time_get_uptime_secs();
  cmss_orig_thr_table_q_type *thr_tbl_entry_ptr;

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
  if(thr_tbl_ptr == NULL)
  {
    sys_err_fatal_null_ptr_exception();
    return FALSE;
  }

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  sd_misc_sys_id_print( sys_id );

  thr_tbl_entry_ptr = cmss_orig_thr_get_orig_tbl_entry(
                        thr_tbl_ptr, sys_id, band_class, packet_zone );

  if( thr_tbl_entry_ptr == NULL )
  {
    return FALSE;
  }

  CM_MSG_HIGH_2("Orig. Thr. uptime %d curr uptime %d",
                thr_tbl_entry_ptr->cmss_orig_thr_tbl.thr_uptime, uptime);
  if( call_type != CM_CALL_TYPE_NONE )
  {
    return( CM_BOOLEAN
            (
              ( call_type == thr_tbl_entry_ptr->cmss_orig_thr_tbl.orig_call_info.call_type )
              &&
              ( uptime     < thr_tbl_entry_ptr->cmss_orig_thr_tbl.thr_uptime )
            )
          );

  }
  if( uptime < thr_tbl_entry_ptr->cmss_orig_thr_tbl.thr_uptime )
  {
    return TRUE;
  }

  return FALSE;

} /* cmss_check_if_orig_thr_true */


/*===========================================================================

FUNCTION cmss_initialize_thr_status

DESCRIPTION
  This function initializes the throttle status pointer to the values passed

DEPENDENCIES
  cmss_init() should have been called previously.

RETURN VALUE
  None.

SIDE EFFECTS
  None.
===========================================================================*/
static void cmss_initialize_thr_status(

  cm_ss_orig_thr_call_status_s_type *throttle_status,
  /* The pointer to be initialized
  */

  cm_call_type_e_type                call_type,
  /* Call Type
  */

  cm_call_end_e_type                 end_status,
  /* Call end status
  */

  boolean                            is_hdr_sys_id,
  /* Flag to use hdr_sys_id
  */
  sys_modem_as_id_e_type             asubs_id
)
{

  cm_mm_ss_info_sub_prop_s_type *ss_sub_ptr = cmss_get_info_sub_prop(asubs_id);
  cm_mm_ss_info_gen_stack_info_s_type *ss_stack_ptr, *ss_stack1_ptr;
  if(ss_sub_ptr == NULL ||
      ss_sub_ptr->stack_info[MM_STACK_0].gen_info == NULL)
  {
    return;
  }
  ss_stack_ptr = ss_sub_ptr->stack_info[MM_STACK_0].gen_info;
  ss_stack1_ptr = ss_sub_ptr->stack_info[MM_STACK_1].gen_info;
  CM_ASSERT(throttle_status != NULL);

  throttle_status->call_type    = call_type;
  throttle_status->mode_info.cdma_info = ss_stack_ptr->mode_info.cdma_info;
  throttle_status->call_status  =
    cmss_map_call_end_status_to_thr_status(end_status);

  if( !is_hdr_sys_id )
  {
    throttle_status->sys_id     = ss_stack_ptr->sys_id;
    throttle_status->mode_info.cdma_info.band_class = ss_stack_ptr->active_band;
  }
  else if(ss_stack1_ptr != NULL)
  {
    throttle_status->sys_id     = ss_stack1_ptr->sys_id;
    throttle_status->mode_info.cdma_info.band_class = ss_stack1_ptr->active_band;
  }

  return;
} /* cmss_initialize_thr_status */



/*===========================================================================

FUNCTION cmss_check_if_orig_thr_and_add_entry

DESCRIPTION
  This function checks if the call origination needs to be throttled, and
  if it needs to be throttled then adds a entry in the origination throttle
  table

DEPENDENCIES
  cmss_init() should have been called previously.

RETURN VALUE
  True: If the call is throttled and the entry made in the table
  False: Otherwise

SIDE EFFECTS
  None.
===========================================================================*/
boolean cmss_check_if_orig_thr_and_add_entry(

  cm_call_type_e_type   call_type,
  /* Call type - VOICE, SMS, E911, etc
  */
  cm_call_end_e_type    end_status,
  /* Call end status
  */
  boolean               is_hdr,
  /* Flag to use hdr_sys_id
  */
  sys_modem_as_id_e_type  asubs_id
)
{
  boolean is_orig_throttle = FALSE;
  cmss_misc_sub_prop_s_type *ss_misc_sub_ptr = cmss_get_misc_sub_prop_ptr(asubs_id);

  if( ss_misc_sub_ptr == NULL ||
      !cmutil_is_as_id_valid(asubs_id)||
      call_type != CM_CALL_TYPE_PS_DATA)
  {
    return FALSE;
  }

  is_orig_throttle = cmss_check_if_orig_thr_end_status( end_status );

  if( is_orig_throttle )
  {
    cm_ss_orig_thr_call_status_s_type throttle_status;

    if( !is_hdr )
    {
      cmss_initialize_thr_status( &throttle_status,
                                  call_type,
                                  end_status,
                                  FALSE,
                                  asubs_id);
    }
    else
    {
      cmss_initialize_thr_status( &throttle_status,
                                  call_type,
                                  end_status,
                                  TRUE,
                                  asubs_id);
    }

    /* We are ignoring NID, so replace it with the wild card nid
    */

    if( throttle_status.sys_id.id_type == SYS_SYS_ID_TYPE_IS95 )
    {
      throttle_status.sys_id.id.is95.nid  = SD_WILDCARD_NID;
    }

    is_orig_throttle =  cmss_orig_thr_update_tbl_entry_with_call_status(
                          cmss_ptr()->cmss_orig_thr_tbl_ptr,
                          &throttle_status,
                          asubs_id);
    return( is_orig_throttle ) ;

  } /* if(is_orig_throttle) */

  return FALSE;
}/* cmss_check_if_orig_thr_add_entry */


/*===========================================================================

FUNCTION cmss_misc_set_ss_info_thr_status

DESCRIPTION
  This function ssets the ss_thr_status of the ss object

DEPENDENCIES

RETURN VALUE
  None.

SIDE EFFECTS
  None.
===========================================================================*/

void cmss_misc_set_ss_info_thr_status(
  sys_modem_as_id_e_type  asubs_id
)
{
  if(cmss_update_thr_status(asubs_id))
  {
    cmss_event(cmph_map_sub_stk_to_id(asubs_id, MM_STACK_0), CM_SS_EVENT_SRV_CHANGED);
  }
  return;

}/* cmss_misc_set_ss_info_thr_status */

#endif /* FEATURE_CALL_THROTTLE */


sys_sys_mode_e_type cmss_map_access_tech_to_sys_mode
(
  sys_radio_access_tech_e_type rat
)
{
  sys_sys_mode_e_type sys_mode = SYS_SYS_MODE_NO_SRV;

  switch(rat)
  {
    case SYS_RAT_GSM_RADIO_ACCESS:
      sys_mode = SYS_SYS_MODE_GSM;
      break;

    case SYS_RAT_UMTS_RADIO_ACCESS:
      sys_mode = SYS_SYS_MODE_WCDMA;
      break;

    case SYS_RAT_LTE_RADIO_ACCESS:
      sys_mode = SYS_SYS_MODE_LTE;
      break;

    case SYS_RAT_TDS_RADIO_ACCESS:
      sys_mode = SYS_SYS_MODE_TDS;
      break;

    default:
      sys_mode = SYS_SYS_MODE_NO_SRV;
      break;
  }

  return sys_mode;

}

/*===========================================================================

FUNCTION cmss_get_ss_main_info_change

DESCRIPTION
  Compares the serving system information change and returns
  a bit mask holding difference.

DEPENDENCIES
  Phone object must have already been initialized with
  cmph_init().

RETURN VALUE
  Bit Mask indicating which of the Serving System parameters changed

SIDE EFFECTS
  none

===========================================================================*/
static uint64 cmss_get_ss_main_info_change(

  const cm_mm_ss_info_s_type     *new_srv_info,
  /*  New SS information */

  const cm_mm_msim_ss_info_s_type  *old_srv_info,
  /*  Old SS information */

  uint64 *changed_fields2,

  sys_modem_as_id_e_type  as_id
)
/*lint -esym(715,changed_fields2)*/
/*lint -esym(818,changed_fields2)*/
{

  uint8                             stk_id =  cmss_map_stack_id_to_client_stk(MM_STACK_0);
  /* Records the changes in SS parameters between new_srv_info and old_srv_info */
  uint64                        changed_fields = 0;

  /* Point at serving system object to be initialized */
  cmss_misc_sub_prop_s_type *ss_misc_sub_ptr = cmss_get_misc_sub_prop_ptr(as_id);
  cmss_misc_3gpp_stack_info_s_type *ss_misc_stack0_gpp_ptr, *ss_misc_stack2_gpp_ptr;
  /*lint -esym(529, ss_ptr) not referenced */
  const sys_time_info_s_type *old_time = &(old_srv_info->stack_info[0].mode_info.cdma_info.time_info);

  const sys_time_info_s_type         *new_time = CDMA_TIME_PTR(new_srv_info, as_id);
  cm_mm_ss_info_sub_prop_s_type *ss_sub_ptr;
  multimode_stack_e_type stack_id = MM_STACK_0;
  cm_mm_ss_info_3gpp_stack_info_s_type *ss_info_gpp_stack_ptr;
  cm_mm_ss_info_gen_stack_info_s_type *ss_stack_ptr, *ss_stack1_ptr;
  cm_mm_ss_info_3gpp2_stack_info_s_type *ss_info_gpp2_stack_ptr;

  if(new_srv_info == NULL || !cmutil_is_as_id_valid(as_id) ||
      new_srv_info->sub_prop[as_id] == NULL || ss_misc_sub_ptr == NULL)
  {
    return changed_fields;
  }
  ss_sub_ptr    = new_srv_info->sub_prop[as_id];
  ss_stack_ptr   = ss_sub_ptr->stack_info[stack_id].gen_info;
  ss_stack1_ptr = ss_sub_ptr->stack_info[MM_STACK_1].gen_info;
  ss_info_gpp_stack_ptr   = ss_sub_ptr->stack_info[stack_id].gpp_info;
  ss_info_gpp2_stack_ptr  = ss_sub_ptr->stack_info[stack_id].gpp2_info;
  ss_misc_stack0_gpp_ptr = ss_misc_sub_ptr->stack_info[stack_id].gpp_info;
  ss_misc_stack2_gpp_ptr = ss_misc_sub_ptr->stack_info[MM_STACK_2].gpp_info;

  if(ss_stack_ptr == NULL || ss_info_gpp_stack_ptr == NULL || ss_info_gpp2_stack_ptr == NULL)
  {
    return changed_fields;
  }
  if (old_srv_info != NULL)
  {
    /*
    ** If service state changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_stack_ptr->srv_status != old_srv_info->stack_info[stk_id].srv_status )
    {
      changed_fields |= CM_SS_SRV_STATUS_MASK;
    }

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If true service status changed,
    ** then also notify CM clients of the event.
    */
    if (ss_info_gpp_stack_ptr->true_srv_status != old_srv_info->stack_info[stk_id].true_srv_status )
    {
      changed_fields |= CM_SS_TRUE_SRV_STATUS_MASK;
    }

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If system mode changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_stack_ptr->sys_mode != old_srv_info->stack_info[stk_id].sys_mode )
    {
      changed_fields |= CM_SS_SYS_MODE_MASK;
    }

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If active band changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_stack_ptr->active_band != old_srv_info->stack_info[stk_id].active_band )
    {
      changed_fields |= CM_SS_ACTIVE_BAND_MASK;
    }

    /*
    ** If active chan changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_stack_ptr->active_channel != old_srv_info->stack_info[stk_id].active_channel )
    {
      changed_fields |= CM_SS_ACTIVE_CHANNEL_MASK;
    }

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If roaming status changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_stack_ptr->roam_status != old_srv_info->stack_info[stk_id].roam_status )
    {
      changed_fields |= CM_SS_ROAM_STATUS_MASK;
    }

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If srv domain changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_stack_ptr->srv_domain != old_srv_info->stack_info[stk_id].srv_domain )
    {
      changed_fields |= CM_SS_SRV_DOMAIN_MASK;
    }


    /* Set the mask if SRV_EVENT_CHANGED is in response to CM_SS_CMD_GET_DCH_CELL_ID */
#if (defined(FEATURE_WCDMA_CM_CID_UPDATE_IN_DCH) && defined(FEATURE_WCDMA))
    if(ss_misc_sub_ptr == NULL)
    {
      return changed_fields;
    }
    /* Set the mask if SS event is due to CELL_INFO_CNF from RRC */
    if(ss_stack_ptr->sys_mode == SYS_SYS_MODE_WCDMA)
    {
      if (ss_misc_sub_ptr->sub_info.gen_sub_info.dch_cell_info_flgs & CMSS_IS_DCH_CELL_INFO_RES)
      {
        changed_fields |= CM_SS_CELLID_DCH_MASK;
      }
      else
      {
        changed_fields &= (~CM_SS_CELLID_DCH_MASK);
      }
    }
#endif

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If srv capability changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_info_gpp_stack_ptr->srv_capability != old_srv_info->stack_info[stk_id].srv_capability )
    {
      changed_fields |= CM_SS_SRV_CAPABILITY_MASK;
    }

    /*
    ** If the system identifier has changed, notify CM clients of the
    ** corresponding event.
    */
    if ( !cmss_sys_id_match( ss_stack_ptr->sys_id, old_srv_info->stack_info[stk_id].sys_id ) )
    {
      changed_fields |= CM_SS_SYS_ID_MASK;

#ifdef CM_GW_SUPPORTED
      /*
      ** If the PLMN changed or there is no service, then clear the mobility
      ** management information.
      */
      if (((CM_IS_MODE_3GPP(old_srv_info->stack_info[stk_id].sys_mode))||(CM_IS_MODE_3GPP(ss_stack_ptr->sys_mode)))
          && ss_stack_ptr->sys_mode == cmss_map_access_tech_to_sys_mode(ss_stack_ptr->mode_info.gw_info.mm_information.rat))
      {
        changed_fields |= CM_SS_MOBILITY_MGMT_MASK;
      }

#endif  /* FEATURE_WCDMA || FEATURE_GSM */

      /*
      ** Decide whether the SID and NID Mask fields need to be set also.
      */
      if ((ss_stack_ptr->sys_id.id_type == SYS_SYS_ID_TYPE_IS95) &&
          (old_srv_info->stack_info[stk_id].sys_id.id_type == SYS_SYS_ID_TYPE_IS95))
      {
        if (ss_stack_ptr->sys_id.id.is95.nid != old_srv_info->stack_info[stk_id].sys_id.id.is95.nid)
        {
          changed_fields |= CM_SS_NID_MASK;
        }

        if (ss_stack_ptr->sys_id.id.is95.sid != old_srv_info->stack_info[stk_id].sys_id.id.is95.sid)
        {
          changed_fields |= CM_SS_SID_MASK;
        }
        if( ss_stack_ptr->sys_id.id.is95.mcc != old_srv_info->stack_info[stk_id].sys_id.id.is95.mcc )
        {
          changed_fields |= CM_SS_MCC_MASK;
        }

        if(ss_stack_ptr->sys_id.id.is95.imsi_11_12 != old_srv_info->stack_info[stk_id].sys_id.id.is95.imsi_11_12 )
        {
          changed_fields |= CM_SS_IMSI_11_12_MASK;
        }
      }
      else if ((ss_stack_ptr->sys_id.id_type == SYS_SYS_ID_TYPE_IS95) &&
               (old_srv_info->stack_info[stk_id].sys_id.id_type != SYS_SYS_ID_TYPE_IS95))
      {
        changed_fields |= CM_SS_NID_MASK;
        changed_fields |= CM_SS_SID_MASK;
        changed_fields |= CM_SS_MCC_MASK;
        changed_fields |= CM_SS_IMSI_11_12_MASK;
      }
    }

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If default roaming indicator changed, notify CM clients of the
    ** corresponding event.
    */
    if ( ss_sub_ptr->sub_info.gen_sub_info.def_roam_ind != old_srv_info->def_roam_ind )
    {
      changed_fields |= CM_SS_DEF_ROAM_IND_MASK;
    }

    /*
    ** If prl match status changed, notify CM clients of the
    ** corresponding event.
    */
    if ( ss_info_gpp_stack_ptr->is_sys_prl_match != old_srv_info->stack_info[stk_id].is_sys_prl_match )
    {
      changed_fields |= CM_SS_SYS_PRL_MATCH_MASK;
    }

    /*
    ** If system forbidden status changed, notify CM clients of the
    ** corresponding event.
    */
    if ( ss_info_gpp_stack_ptr->is_sys_forbidden != old_srv_info->stack_info[stk_id].is_sys_forbidden )
    {
      changed_fields |= CM_SS_SYS_FORBIDDEN_MASK;
    }


    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** Check if any mode specific info changed - base station lat or long or
    ** base id or srch_win_n.
    */
    if ( ss_stack_ptr->sys_mode == SYS_SYS_MODE_CDMA  &&
         old_srv_info->stack_info[stk_id].sys_mode == ss_stack_ptr->sys_mode &&
         ( ss_stack_ptr->mode_info.cdma_info.base_lat !=
             old_srv_info->stack_info[stk_id].mode_info.cdma_info.base_lat ||
           ss_stack_ptr->mode_info.cdma_info.base_long !=
             old_srv_info->stack_info[stk_id].mode_info.cdma_info.base_long ||
           ss_stack_ptr->mode_info.cdma_info.base_id !=
             old_srv_info->stack_info[stk_id].mode_info.cdma_info.base_id ||
           ss_stack_ptr->mode_info.cdma_info.srch_win_n !=
             old_srv_info->stack_info[stk_id].mode_info.cdma_info.srch_win_n
         )
       )
    {
      changed_fields |= CM_SS_BASE_STATION_PARMS_CHGD_MASK;
    }

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If throttle status on main (1x or non hybrid HDR)
    ** has changed notify CM clients of the corresponding event.
    */
#ifdef FEATURE_CALL_THROTTLE
    if (   ss_info_gpp2_stack_ptr->gpp2_thr_status.ss_thr_status !=
           old_srv_info->stack_info[stk_id].thr_status.ss_thr_status
       )
    {
      changed_fields |= CM_SS_ORIG_THR_STATUS_MASK;
    }
#endif /* FEATURE_CALL_THROTTLE */

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If the HDR system identifier has changed, notify CM clients of the
    ** corresponding event.
    */
#ifdef FEATURE_HDR_HYBRID

    if(ss_stack_ptr->sys_mode == SYS_SYS_MODE_HDR ||
        (ss_stack1_ptr != NULL && ss_stack1_ptr->sys_mode == SYS_SYS_MODE_HDR))
    {
      if ( ss_stack1_ptr != NULL &&
           !cmss_sys_id_match( ss_stack1_ptr->sys_id, old_srv_info->stack_info[1].sys_id ) )
      {
        changed_fields |= CM_SS_HDR_SYS_ID_MASK;
      }
    }
#endif /* FEATURE_HYBR_HDR */

    if( ss_sub_ptr->sub_info.gen_sub_info.psist != old_srv_info->stack_info[stk_id].psist )
    {
      changed_fields |= CM_SS_PSIST_CHGD_MASK;
    }
#if defined (FEATURE_LTE_TO_1X)
    if( ss_sub_ptr->sub_info.gen_sub_info.is_csfb_call_active != old_srv_info->is_csfb_call_active )
    {
      changed_fields |= CM_SS_CSFB_CALL_ACTIVE_MASK;
    }
#endif
#ifdef FEATURE_BCMCS
    if(ss_info_gpp2_stack_ptr->ss_bcmcs_srv_status !=
        old_srv_info->stack_info[stk_id].bcmcs_srv_status )
    {
      changed_fields |= CM_SS_MAIN_BCMCS_SRV_STATUS_MASK;
    }
#endif
    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
    /*lint -save -e539 -e525 */
    /* If HS indication has changed, set mask
    */
    if( ss_info_gpp_stack_ptr->cell_srv_ind.hs_ind
          != old_srv_info->stack_info[stk_id].cell_srv_ind.hs_ind )
    {
      changed_fields |= CM_SS_SRV_IND_MASK;
    }

    /* If HS call indication has changed, set mask
      */
    if ( ss_info_gpp_stack_ptr->cell_srv_ind.hs_call_status
           != old_srv_info->stack_info[stk_id].cell_srv_ind.hs_call_status)
    {
      changed_fields |= CM_SS_SRV_IND_MASK;
    }

    /* If DTM indication has changed, set mask
    */
    if ( ss_info_gpp_stack_ptr->cell_srv_ind.dtm_supp
           != old_srv_info->stack_info[stk_id].cell_srv_ind.dtm_supp )
    {
      changed_fields |= CM_SS_SRV_IND_MASK;
    }
    /* If EGPRS indication has changed, set mask
    */
    if ( ss_info_gpp_stack_ptr->cell_srv_ind.egprs_supp
           != old_srv_info->stack_info[stk_id].cell_srv_ind.egprs_supp )
    {
      changed_fields |= CM_SS_SRV_IND_MASK;
    }

    /*
    ** Check if cell_info specific info changed
    */

    if ( ss_info_gpp_stack_ptr->cell_info.cell_id             != old_srv_info->stack_info[stk_id].cell_info.cell_id             ||
         ss_info_gpp_stack_ptr->cell_info.as_sys_mode         != old_srv_info->stack_info[stk_id].cell_info.as_sys_mode         ||
         ss_info_gpp_stack_ptr->cell_info.plmn_id.identity[0] != old_srv_info->stack_info[stk_id].cell_info.plmn_id.identity[0] ||
         ss_info_gpp_stack_ptr->cell_info.plmn_id.identity[1] != old_srv_info->stack_info[stk_id].cell_info.plmn_id.identity[1] ||
         ss_info_gpp_stack_ptr->cell_info.plmn_id.identity[2] != old_srv_info->stack_info[stk_id].cell_info.plmn_id.identity[2])

    {
      changed_fields |= CM_SS_CELL_INFO_MASK;
    }


    if(ss_info_gpp_stack_ptr->cell_info.emerg_access_status != old_srv_info->stack_info[stk_id].cell_info.emerg_access_status)
    {
      *changed_fields2 |= CM_SS_LTE_EMERG_ACCESS_BARRED_MASK;
    }

    if(ss_info_gpp_stack_ptr->cell_info.lte_cell_access_status != old_srv_info->stack_info[stk_id].cell_info.lte_cell_access_status)
    {
      *changed_fields2 |= CM_SS_LTE_CELL_ACCESS_STATUS_MASK;
    }
    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*lint -restore */

#ifdef FEATURE_HDR

    /* If HDR active protocol is changed, set mask
    */


    if(ss_stack_ptr->sys_mode == SYS_SYS_MODE_HDR ||
        (ss_stack1_ptr != NULL && ss_stack1_ptr->srv_status == SYS_SRV_STATUS_SRV)
        || old_srv_info->stack_info[cmss_map_stack_id_to_client_stk(MM_STACK_1)].sys_mode == SYS_SYS_MODE_HDR)
    {
      if( ss_sub_ptr->sub_info.gpp2_sub_info.hdr_gen_info.hdr_active_prot != old_srv_info->stack_info[cmss_map_stack_id_to_client_stk(MM_STACK_1)].rat_mode_info.hdr_mode_info.hdr_active_prot )
      {
        changed_fields |= CM_SS_HDR_ACTIVE_PROT_MASK;
      }

      /* If HDR personality is changed, set mask
      */

      if( ss_sub_ptr->sub_info.gpp2_sub_info.hdr_signal_info.hdr_personality != old_srv_info->stack_info[cmss_map_stack_id_to_client_stk(MM_STACK_1)].rat_mode_info.hdr_mode_info.hdr_personality )
      {
        changed_fields |= CM_SS_HDR_PERSONALITY_MASK;
      }
    }
#endif //FEATURE_HDR



    /*
    ** If there is a CDMA time change, notify clients
    ** Note that the UE may traverse between 3GPP and 3GPP2, and the
    ** new_time, old_time are part of the union.
    */
    /* Transition to CDMA or HDR */
    if ( ( ss_stack_ptr->sys_mode == SYS_SYS_MODE_CDMA||
           ss_stack_ptr->sys_mode == SYS_SYS_MODE_HDR))
    {
      if ( old_srv_info->stack_info[stk_id].sys_mode == SYS_SYS_MODE_CDMA||
           old_srv_info->stack_info[stk_id].sys_mode == SYS_SYS_MODE_HDR)
      {
        if ( cmss_is_cdma_time_chgd(old_time,new_time))
        {
          changed_fields |= CM_SS_CDMA_TIME_CHGD_MASK;
        }
      }
      else
      {
        changed_fields |= CM_SS_CDMA_TIME_CHGD_MASK;
      }
    } // time conditions

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
    /*
    ** If in GW service, LAC or RAC changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_stack_ptr->srv_status == SYS_SRV_STATUS_SRV &&
         (ss_stack_ptr->sys_mode  == SYS_SYS_MODE_GSM ||
          ss_stack_ptr->sys_mode  == SYS_SYS_MODE_WCDMA ||
          ss_stack_ptr->sys_mode  == SYS_SYS_MODE_TDS)
       )
    {


      switch(ss_stack_ptr->sys_mode)
      {
        case SYS_SYS_MODE_GSM:
          if(ss_info_gpp_stack_ptr->gpp_signal_info.rac_or_mme_code !=  old_srv_info->stack_info[stk_id].rat_mode_info.gsm_mode_info.rac_or_mme_code)
          {
            changed_fields |= CM_SS_LAC_TAC_RAC_CHGD_MASK;
          }
          if(ss_info_gpp_stack_ptr->gpp_signal_info.lac !=  old_srv_info->stack_info[stk_id].rat_mode_info.gsm_mode_info.lac)
          {
            changed_fields |= CM_SS_LAC_TAC_RAC_CHGD_MASK;
          }
          break ;

        case SYS_SYS_MODE_WCDMA:
          if(ss_info_gpp_stack_ptr->gpp_signal_info.lac !=  old_srv_info->stack_info[stk_id].rat_mode_info.wcdma_mode_info.lac)
          {
            changed_fields |= CM_SS_LAC_TAC_RAC_CHGD_MASK;
          }

          if(ss_info_gpp_stack_ptr->gpp_signal_info.rac_or_mme_code!=old_srv_info->stack_info[stk_id].rat_mode_info.wcdma_mode_info.rac_or_mme_code)
          {
            changed_fields |= CM_SS_LAC_TAC_RAC_CHGD_MASK;
          }
          break ;

        case SYS_SYS_MODE_TDS:
          if(ss_info_gpp_stack_ptr->gpp_signal_info.lac !=  old_srv_info->stack_info[stk_id].rat_mode_info.tds_mode_info.lac )
          {
            changed_fields |= CM_SS_LAC_TAC_RAC_CHGD_MASK;
          }

          if(ss_info_gpp_stack_ptr->gpp_signal_info.rac_or_mme_code!= old_srv_info->stack_info[stk_id].rat_mode_info.tds_mode_info.rac_or_mme_code)
          {
            changed_fields |= CM_SS_LAC_TAC_RAC_CHGD_MASK;
          }
          break ;

        default:
          break;

      }
    }

#ifdef FEATURE_CM_LTE
    /*
    ** If in LTE service, TAC or RAC changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_stack_ptr->srv_status == SYS_SRV_STATUS_SRV &&
         ss_stack_ptr->sys_mode   == SYS_SYS_MODE_LTE
       )
    {
      if(ss_info_gpp_stack_ptr->gpp_signal_info.tac !=  old_srv_info->stack_info[stk_id].rat_mode_info.lte_mode_info.tac)
      {
        changed_fields |= CM_SS_LAC_TAC_RAC_CHGD_MASK;
      }
      if(ss_info_gpp_stack_ptr->gpp_signal_info.rac_or_mme_code !=  old_srv_info->stack_info[stk_id].rat_mode_info.lte_mode_info.rac_or_mme_code)
      {
        changed_fields |= CM_SS_LAC_TAC_RAC_CHGD_MASK;
      }

      if(ss_sub_ptr->sub_info.gen_sub_info.embms_info.embms_coverage_status !=  old_srv_info->stack_info[stk_id].rat_mode_info.lte_mode_info.embms_info.embms_coverage_status)
      {
        changed_fields |= CM_SS_LTE_EMBMS_INFO_MASK;
      }
    }

    /*
    ** If div_duplex of  MAIN/HYBR2 info is changed, notify CM clients
    ** of the corresponding event.
    */

    if((ss_misc_stack0_gpp_ptr != NULL &&
        ss_misc_stack0_gpp_ptr->div_duplex != old_srv_info->div_duplex )
        && ss_misc_stack0_gpp_ptr->div_duplex != SYS_DIV_DUPLEX_UNKNOWN
        && (!cmss_is_stack2_operational(as_id) ||
            cmph_is_lte_capable_on_sub(as_id)))
    {
      changed_fields |= CM_SS_DIV_DUPLEX_MASK;
    }
    else if((ss_misc_stack2_gpp_ptr != NULL &&
             ss_misc_stack2_gpp_ptr->div_duplex != old_srv_info->div_duplex )
            && ss_misc_stack2_gpp_ptr->div_duplex != SYS_DIV_DUPLEX_UNKNOWN
            && (cmss_is_stack2_operational(as_id) &&
                (cmph_is_subs_feature_mode_1x_sxlte(as_id) )))
    {
      changed_fields |= CM_SS_DIV_DUPLEX_MASK;
    }

    /*
    ** If voice over PS indication changed, notify CM clients of the corresponding
    ** event.
    */
    if(ss_sub_ptr->sub_info.gen_sub_info.dom_sel_info.lte_ims_voice_avail != old_srv_info->stack_info[stk_id].lte_ims_voice_avail)
    {
      changed_fields |= CM_SS_LTE_IMS_VOICE_AVAIL_MASK;
    }

    if(ss_sub_ptr->sub_info.gen_sub_info.dom_sel_info.lte_cs_capability != old_srv_info->stack_info[stk_id].lte_cs_capability)
    {
      *changed_fields2 |= CM_SS_LTE_CS_CAPABILITY_MASK;
    }
    /* update if there is change to emerg bearer support over LTE
    */
    if((!(cmph_is_subs_feature_mode_svlte(as_id)) || !cmss_is_stack2_operational(as_id) ) &&
        (cmcall_misc_is_mode_pref((cmph_get_ss_mode_pref(as_id)), CM_MODE_PREF_LTE_ONLY)) &&
        (ss_sub_ptr->sub_info.gen_sub_info.dom_sel_info.lte_ims_emerg_avail != old_srv_info->stack_info[stk_id].lte_ims_emerg_avail))
    {
      *changed_fields2 |= CM_SS_LTE_IMS_EMERG_AVAIL_MASK;
    }

#ifdef FEATURE_DOMAIN_SELECTION
    if (ss_sub_ptr->sub_info.gen_sub_info.dom_sel_info.voice_domain != old_srv_info->voice_domain)
    {
      *changed_fields2 |= CM_SS_LTE_VOICE_DOMAIN_CHANGED_MASK;
    }

    if (ss_sub_ptr->sub_info.gen_sub_info.dom_sel_info.sms_domain != old_srv_info->sms_domain)
    {
      *changed_fields2 |= CM_SS_LTE_SMS_DOMAIN_CHANGED_MASK;
    }
#endif


    if( ss_sub_ptr->sub_info.gen_sub_info.available_plmn_type != old_srv_info->stack_info[stk_id].available_plmn_type )
    {
      *changed_fields2 |= CM_SS_SGLTE_REG_DOMAIN_CHANGED_MASK;
    }


#endif

    if ( old_srv_info->stack_info[stk_id].cell_bc_info.cell_bc_capability !=
         ss_sub_ptr->sub_info.gen_sub_info.cell_bc_info.cell_bc_capability)
    {
      changed_fields |= CM_SS_CELL_BROADCAST_MASK;
      CM_MSG_MED_0 ("Cell Broadcast chg");
    }

    if( old_srv_info->bsr_in_progress !=
        ss_sub_ptr->sub_info.gpp2_sub_info.bsr_in_progress)
    {
      changed_fields |= CM_SS_BSR_PROGRESS_MASK;
    }

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
    switch(ss_stack_ptr->sys_mode)
    {
      case  SYS_SYS_MODE_LTE:
        if ( !(old_srv_info->stack_info[stk_id].rat_mode_info.lte_mode_info.csg_info.csg_id == SYS_CSG_ID_INVALID && new_srv_info->device_prop.csg_info.csg_id == SYS_CSG_ID_INVALID) &&
             ( 0 != memcmp(&(old_srv_info->stack_info[stk_id].rat_mode_info.lte_mode_info.csg_info), &(new_srv_info->device_prop.csg_info), sizeof(sys_csg_info_s_type)) || \
               ( (new_srv_info->device_prop.csg_info.csg_id != SYS_CSG_ID_INVALID ) && \
                 (ss_stack_ptr->sys_id.id_type == SYS_SYS_ID_TYPE_UMTS ) && \
                 (!cmss_sys_id_match( ss_stack_ptr->sys_id, old_srv_info->stack_info[stk_id].sys_id ))))
           )
        {
          changed_fields |= CM_SS_CSG_INFO_CHANGED_MASK;
          CM_MSG_HIGH_1 ("CSG Information Changed. new CSG_ID=%d",new_srv_info->device_prop.csg_info.csg_id);
        }

        break;

      case  SYS_SYS_MODE_GSM:
        if ( !(old_srv_info->stack_info[stk_id].rat_mode_info.gsm_mode_info.csg_info.csg_id == SYS_CSG_ID_INVALID && new_srv_info->device_prop.csg_info.csg_id == SYS_CSG_ID_INVALID) &&
             ( 0 != memcmp(&(old_srv_info->stack_info[stk_id].rat_mode_info.gsm_mode_info.csg_info), &(new_srv_info->device_prop.csg_info), sizeof(sys_csg_info_s_type)) || \
               ( (new_srv_info->device_prop.csg_info.csg_id != SYS_CSG_ID_INVALID ) && \
                 (ss_stack_ptr->sys_id.id_type == SYS_SYS_ID_TYPE_UMTS ) && \
                 (!cmss_sys_id_match( ss_stack_ptr->sys_id, old_srv_info->stack_info[stk_id].sys_id ))))
           )
        {
          changed_fields |= CM_SS_CSG_INFO_CHANGED_MASK;
          CM_MSG_MED_1 ("CSG GSM Information Changed. new CSG_ID=%d",new_srv_info->device_prop.csg_info.csg_id);
        }

        break ;

      case  SYS_SYS_MODE_WCDMA:
        if ( !(old_srv_info->stack_info[stk_id].rat_mode_info.wcdma_mode_info.csg_info.csg_id == SYS_CSG_ID_INVALID && new_srv_info->device_prop.csg_info.csg_id == SYS_CSG_ID_INVALID) &&
             ( 0 != memcmp(&(old_srv_info->stack_info[stk_id].rat_mode_info.wcdma_mode_info.csg_info), &(new_srv_info->device_prop.csg_info), sizeof(sys_csg_info_s_type)) || \
               ( (new_srv_info->device_prop.csg_info.csg_id != SYS_CSG_ID_INVALID ) && \
                 (ss_stack_ptr->sys_id.id_type == SYS_SYS_ID_TYPE_UMTS ) && \
                 (!cmss_sys_id_match( ss_stack_ptr->sys_id, old_srv_info->stack_info[stk_id].sys_id ))))
           )
        {
          changed_fields |= CM_SS_CSG_INFO_CHANGED_MASK;
          CM_MSG_MED_1 ("CSG WCDMA Information Changed. new CSG_ID=%d",new_srv_info->device_prop.csg_info.csg_id);
        }

        break ;

      default:
        break;



    }

    if( ss_info_gpp_stack_ptr->reg_reject_info.reject_cause != old_srv_info->stack_info[stk_id].reg_reject_info.reject_cause ||
        ss_info_gpp_stack_ptr->reg_reject_info.reject_srv_domain != old_srv_info->stack_info[stk_id].reg_reject_info.reject_srv_domain)
    {
      *changed_fields2 |= CM_SS_LU_REJECT_MASK;
      CM_MSG_MED_4 ("LU reject info chg, reject_srv_domain %d->%d, reject_cause %d->%d",
                       old_srv_info->stack_info[stk_id].reg_reject_info.reject_srv_domain,
                       ss_info_gpp_stack_ptr->reg_reject_info.reject_srv_domain,
                       old_srv_info->stack_info[stk_id].reg_reject_info.reject_cause,
                       ss_info_gpp_stack_ptr->reg_reject_info.reject_cause);
    }

  //Update the changed fields with the bitmask only for LTE.
   if (ss_stack_ptr->sys_mode == SYS_SYS_MODE_LTE) 
   {
    if ( old_srv_info->stack_info[stk_id].rat_mode_info.lte_mode_info.voice_support_on_lte !=
         ss_sub_ptr->sub_info.gen_sub_info.dom_sel_info.voice_support_on_lte )
    {
      changed_fields |= CM_SS_VOICE_SUPPORT_ON_LTE_MASK;
    }
  }
  
    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
  } /* if ((new_srv_info != NULL) && (old_srv_info != NULL)) */

  return changed_fields;

} /* cmss_get_ss_main_info_change () */
/*lint +esym(715,changed_fields2)*/
/*lint +esym(818,changed_fields2)*/



/*===========================================================================
FUNCTION cmss_get_ss_stack_2_info_change

DESCRIPTION
  Compares the serving system information change and returns
  a bit mask holding difference.

DEPENDENCIES
  Phone object must have already been initialized with
  cmph_init().

RETURN VALUE
  Bit Mask indicating which of the Serving System parameters changed

SIDE EFFECTS
  none

===========================================================================*/
static uint64 cmss_get_ss_stack_2_info_change(

  const cm_mm_ss_info_s_type     *new_srv_info,
  /*  New SS information */

  const cm_mm_msim_ss_info_s_type     *old_srv_info,
  /*  Old SS information */

  uint64                   *changed_fields2,

  sys_modem_as_id_e_type    asubs_id
)
{
  uint8                    stk_id =  cmss_map_stack_id_to_client_stk(MM_STACK_2);
  uint64                        changed_fields = 0;

#if defined(FEATURE_MMODE_DUAL_SIM)
#if (defined(FEATURE_WCDMA_CM_CID_UPDATE_IN_DCH) && defined (FEATURE_WCDMA))
  cmss_misc_sub_prop_s_type *ss_misc_sub_ptr;
#endif
#endif
  cm_mm_ss_info_sub_prop_s_type *ss_sub_ptr;
  cm_mm_ss_info_3gpp_stack_info_s_type *ss_info_gpp_stack_ptr;
  cm_mm_ss_info_gen_stack_info_s_type *ss_stack_ptr, *ss_stack0_ptr;

  if(new_srv_info == NULL || !cmutil_is_as_id_valid(asubs_id) ||
      new_srv_info->sub_prop[asubs_id] == NULL)
  {
    return changed_fields;
  }
  ss_sub_ptr = new_srv_info->sub_prop[asubs_id];
  ss_info_gpp_stack_ptr = ss_sub_ptr->stack_info[MM_STACK_2].gpp_info;
  ss_stack_ptr = ss_sub_ptr->stack_info[MM_STACK_2].gen_info;
  ss_stack0_ptr = ss_sub_ptr->stack_info[MM_STACK_0].gen_info;
#if defined(FEATURE_MMODE_DUAL_SIM)
#if (defined(FEATURE_WCDMA_CM_CID_UPDATE_IN_DCH) && defined (FEATURE_WCDMA))
  ss_misc_sub_ptr = cmss_get_misc_sub_prop_ptr(asubs_id);
  if(ss_misc_sub_ptr == NULL)
  {
    return changed_fields;
  }
#endif
#endif

  if(ss_stack_ptr == NULL || ss_info_gpp_stack_ptr == NULL || ss_stack0_ptr == NULL)
  {
    return changed_fields;
  }

  /* Records the changes in SS parameters between new_srv_info and old_srv_info */

  if (old_srv_info != NULL)
  {
    /*
    ** If service state changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_stack_ptr->srv_status != old_srv_info->stack_info[stk_id].srv_status )
    {
      changed_fields |= CM_SS_SRV_STATUS_MASK;
    }

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If true service status changed,
    ** then also notify CM clients of the event.
    */
    if (ss_info_gpp_stack_ptr->true_srv_status != old_srv_info->stack_info[stk_id].true_srv_status )
    {
      changed_fields |= CM_SS_TRUE_SRV_STATUS_MASK;
    }

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If system mode changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_stack_ptr->sys_mode != old_srv_info->stack_info[stk_id].sys_mode )
    {
      changed_fields |= CM_SS_SYS_MODE_MASK;
    }
    /* If stack2 is toggled on and has service, send ss event */
    else if (ss_stack_ptr->is_stack_operational &&
             !old_srv_info->stack_info[stk_id].is_operational &&
             cmss_get_true_srv_lte_stk(asubs_id) == MM_STACK_2
            )
    {
      changed_fields |= CM_SS_SYS_MODE_MASK;
    }

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /* Set the mask if SRV_EVENT_CHANGED is in response to CM_SS_CMD_GET_DCH_CELL_ID*/
#ifdef FEATURE_MMODE_DUAL_SIM
    /* Unless it's dual sim configuration, DCH mask(WCDMA) should not be set
    for HYBR2 stack */
#if (defined(FEATURE_WCDMA_CM_CID_UPDATE_IN_DCH) && defined (FEATURE_WCDMA))

    if(ss_stack_ptr->sys_mode == SYS_SYS_MODE_WCDMA)
    {
      if (ss_misc_sub_ptr->sub_info.gen_sub_info.dch_cell_info_flgs & CMSS_IS_DCH_CELL_INFO_RES)
      {
        changed_fields |= CM_SS_CELLID_DCH_MASK;
      }
      else
      {
        ss_stack_ptr->changed_fields &= (~CM_SS_CELLID_DCH_MASK);
      }
    }
#endif
#endif

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If active band changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_stack_ptr->active_band != old_srv_info->stack_info[stk_id].active_band )
    {
      changed_fields |= CM_SS_ACTIVE_BAND_MASK;
    }

    /*
    ** If active chan changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_stack_ptr->active_channel != old_srv_info->stack_info[stk_id].active_channel )
    {
      changed_fields |= CM_SS_ACTIVE_CHANNEL_MASK;
    }

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If roaming status changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_stack_ptr->roam_status != old_srv_info->stack_info[stk_id].roam_status )
    {
      changed_fields |= CM_SS_ROAM_STATUS_MASK;
    }

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If srv domain changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_stack_ptr->srv_domain != old_srv_info->stack_info[stk_id].srv_domain )
    {

      changed_fields |= CM_SS_SRV_DOMAIN_MASK;
    }

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If srv capability changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_info_gpp_stack_ptr->srv_capability != old_srv_info->stack_info[stk_id].srv_capability )
    {
      changed_fields |= CM_SS_SRV_CAPABILITY_MASK;
    }

    /*
    ** If the system identifier has changed, notify CM clients of the
    ** corresponding event.
    */
    if ( !cmss_sys_id_match( ss_stack_ptr->sys_id, old_srv_info->stack_info[stk_id].sys_id ) )
    {
      changed_fields |= CM_SS_SYS_ID_MASK;

#ifdef CM_GW_SUPPORTED
      /*
      ** If the PLMN changed or there is no service, then clear the mobility
      ** management information.
      */

      if (((CM_IS_MODE_3GPP(old_srv_info->stack_info[stk_id].sys_mode))||(CM_IS_MODE_3GPP(ss_stack_ptr->sys_mode)))
          && ss_stack_ptr->sys_mode == cmss_map_access_tech_to_sys_mode(ss_stack_ptr->mode_info.gw_info.mm_information.rat))
      {
        changed_fields |= CM_SS_MOBILITY_MGMT_MASK;
      }
#endif  /* FEATURE_WCDMA || FEATURE_GSM */

    }

    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*
    ** If default roaming indicator changed, notify CM clients of the
    ** corresponding event.

    if ( new_srv_info->def_roam_ind != old_srv_info->def_roam_ind )
    {
      changed_fields |= CM_SS_DEF_ROAM_IND_MASK;
    }*/

    /*
    ** If prl match status changed, notify CM clients of the
    ** corresponding event.
    */
    if ( ss_info_gpp_stack_ptr->is_sys_prl_match != old_srv_info->stack_info[stk_id].is_sys_prl_match )
    {
      changed_fields |= CM_SS_SYS_PRL_MATCH_MASK;
    }

    /*
    ** If system forbidden status changed, notify CM clients of the
    ** corresponding event.
    */
    if ( ss_info_gpp_stack_ptr->is_sys_forbidden != old_srv_info->stack_info[stk_id].is_sys_forbidden )
    {
      changed_fields |= CM_SS_SYS_FORBIDDEN_MASK;
    }

    /*
    ** If in GW service, LAC or RAC changed, notify CM clients of the corresponding
    ** event.
    */
    if ( ss_stack_ptr->srv_status == SYS_SRV_STATUS_SRV &&
         (ss_stack_ptr->sys_mode  == SYS_SYS_MODE_GSM ||
          ss_stack_ptr->sys_mode  == SYS_SYS_MODE_WCDMA ||
          ss_stack_ptr->sys_mode  == SYS_SYS_MODE_TDS)
       )
    {


      switch(ss_stack_ptr->sys_mode)
      {

        case SYS_SYS_MODE_GSM:
          if(ss_info_gpp_stack_ptr->gpp_signal_info.rac_or_mme_code != old_srv_info->stack_info[stk_id].rat_mode_info.gsm_mode_info.rac_or_mme_code)
          {
            changed_fields |= CM_SS_LAC_TAC_RAC_CHGD_MASK;
          }
          if(ss_info_gpp_stack_ptr->gpp_signal_info.lac != old_srv_info->stack_info[stk_id].rat_mode_info.gsm_mode_info.lac)
          {
            changed_fields |= CM_SS_LAC_TAC_RAC_CHGD_MASK;
          }
          break ;

        case SYS_SYS_MODE_WCDMA:
          if(ss_info_gpp_stack_ptr->gpp_signal_info.lac != old_srv_info->stack_info[stk_id].rat_mode_info.wcdma_mode_info.lac)
          {
            changed_fields |= CM_SS_LAC_TAC_RAC_CHGD_MASK;
          }

          if(ss_info_gpp_stack_ptr->gpp_signal_info.rac_or_mme_code!=old_srv_info->stack_info[stk_id].rat_mode_info.wcdma_mode_info.rac_or_mme_code)
          {
            changed_fields |= CM_SS_LAC_TAC_RAC_CHGD_MASK;
          }
          break ;

        case SYS_SYS_MODE_TDS:
          if(ss_info_gpp_stack_ptr->gpp_signal_info.lac != old_srv_info->stack_info[stk_id].rat_mode_info.tds_mode_info.lac )
          {
            changed_fields |= CM_SS_LAC_TAC_RAC_CHGD_MASK;
          }

          if(ss_info_gpp_stack_ptr->gpp_signal_info.rac_or_mme_code!= old_srv_info->stack_info[stk_id].rat_mode_info.tds_mode_info.rac_or_mme_code)
          {
            changed_fields |= CM_SS_LAC_TAC_RAC_CHGD_MASK;
          }
          break ;

        default:
          break;

      }
    }

#ifdef FEATURE_CM_LTE
    if(ss_stack_ptr->sys_mode == SYS_SYS_MODE_LTE)
    {
      if (ss_info_gpp_stack_ptr->gpp_signal_info.tac != old_srv_info->stack_info[stk_id].rat_mode_info.lte_mode_info.tac ||
          ss_info_gpp_stack_ptr->gpp_signal_info.rac_or_mme_code != old_srv_info->stack_info[stk_id].rat_mode_info.lte_mode_info.rac_or_mme_code)
      {
        changed_fields |= CM_SS_LAC_TAC_RAC_CHGD_MASK;
      }
    }
#endif
    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

    /*lint -save -e539 -e525 */
    /* If HS indication has changed, set mask
    */
    if( ss_info_gpp_stack_ptr->cell_srv_ind.hs_ind !=
        old_srv_info->stack_info[stk_id].cell_srv_ind.hs_ind )
    {
      changed_fields |= CM_SS_SRV_IND_MASK;
    }

    /* If HS call indication has changed, set mask
    */
    if ( ss_info_gpp_stack_ptr->cell_srv_ind.hs_call_status !=
         old_srv_info->stack_info[stk_id].cell_srv_ind.hs_call_status)
    {
      changed_fields |= CM_SS_SRV_IND_MASK;
    }

    /* If DTM indication has changed, set mask
    */
    if ( ss_info_gpp_stack_ptr->cell_srv_ind.dtm_supp
           != old_srv_info->stack_info[stk_id].cell_srv_ind.dtm_supp )
    {
      changed_fields |= CM_SS_SRV_IND_MASK;
    }
    /* If EGPRS indication has changed, set mask
    */
    if ( ss_info_gpp_stack_ptr->cell_srv_ind.egprs_supp
           != old_srv_info->stack_info[stk_id].cell_srv_ind.egprs_supp )
    {
      changed_fields |= CM_SS_SRV_IND_MASK;
    }

#ifdef FEATURE_DOMAIN_SELECTION
    if (ss_sub_ptr->sub_info.gen_sub_info.dom_sel_info.voice_domain != old_srv_info->voice_domain)
    {
      *changed_fields2 |= CM_SS_LTE_VOICE_DOMAIN_CHANGED_MASK;
    }

    if (ss_sub_ptr->sub_info.gen_sub_info.dom_sel_info.sms_domain != old_srv_info->sms_domain)
    {
      *changed_fields2 |= CM_SS_LTE_SMS_DOMAIN_CHANGED_MASK;
    }

    /*****************************************************************/
    if (ss_sub_ptr->sub_info.gen_sub_info.dom_sel_info.lte_ims_voice_avail != old_srv_info->stack_info[stk_id].lte_ims_voice_avail)
    {
      changed_fields |= CM_SS_LTE_IMS_VOICE_AVAIL_MASK;
    }

    if(ss_sub_ptr->sub_info.gen_sub_info.dom_sel_info.lte_cs_capability != old_srv_info->stack_info[stk_id].lte_cs_capability)
    {
      *changed_fields2 |= CM_SS_LTE_CS_CAPABILITY_MASK;
    }
    if(((cmph_is_subs_feature_mode_svlte(asubs_id) &&
         cmss_is_stack2_operational(asubs_id)) ||
        (cmph_is_subs_feature_mode_normal(asubs_id) &&
         (cmcall_misc_is_mode_pref(cmph_get_ss_mode_pref(asubs_id), CM_MODE_PREF_LTE_ONLY))))&&
        (ss_sub_ptr->sub_info.gen_sub_info.dom_sel_info.lte_ims_emerg_avail != old_srv_info->stack_info[stk_id].lte_ims_emerg_avail))
    {
      *changed_fields2 |= CM_SS_LTE_IMS_EMERG_AVAIL_MASK;
    }
#endif

    /*
    ** Check if cell_info specific info changed
    */
    if((ss_info_gpp_stack_ptr->cell_info.cell_id != old_srv_info->stack_info[stk_id].cell_info.cell_id )||
        (ss_info_gpp_stack_ptr->cell_info.as_sys_mode != old_srv_info->stack_info[stk_id].cell_info.as_sys_mode ) ||
        (ss_info_gpp_stack_ptr->cell_info.plmn_id.identity[0] != old_srv_info->stack_info[stk_id].cell_info.plmn_id.identity[0]) ||
        (ss_info_gpp_stack_ptr->cell_info.plmn_id.identity[1] != old_srv_info->stack_info[stk_id].cell_info.plmn_id.identity[1]) ||
        (ss_info_gpp_stack_ptr->cell_info.plmn_id.identity[2] != old_srv_info->stack_info[stk_id].cell_info.plmn_id.identity[2]) ||
        (ss_info_gpp_stack_ptr->cell_info.earfcn_dl != old_srv_info->stack_info[stk_id].cell_info.earfcn_dl)
      )
    {
      changed_fields |= CM_SS_CELL_INFO_MASK;
    }

    if(ss_info_gpp_stack_ptr->cell_info.emerg_access_status != old_srv_info->stack_info[stk_id].cell_info.emerg_access_status)
    {
      *changed_fields2 |= CM_SS_LTE_EMERG_ACCESS_BARRED_MASK;
    }

    if(ss_info_gpp_stack_ptr->cell_info.lte_cell_access_status != old_srv_info->stack_info[stk_id].cell_info.lte_cell_access_status)
    {
      *changed_fields2 |= CM_SS_LTE_CELL_ACCESS_STATUS_MASK;
    }
    if ( old_srv_info->stack_info[stk_id].cell_bc_info.cell_bc_capability !=
         ss_sub_ptr->sub_info.gen_sub_info.cell_bc_info.cell_bc_capability)
    {
      changed_fields |= CM_SS_CELL_BROADCAST_MASK;
    }
    if(ss_stack_ptr->sys_mode == SYS_SYS_MODE_LTE)
    {
      if( ss_sub_ptr->sub_info.gen_sub_info.embms_info.embms_coverage_status !=
          old_srv_info->stack_info[stk_id].rat_mode_info.lte_mode_info.embms_info.embms_coverage_status)
      {
        changed_fields |= CM_SS_LTE_EMBMS_INFO_MASK;
      }
    }
    if( ss_info_gpp_stack_ptr->reg_reject_info.reject_cause != old_srv_info->stack_info[stk_id].reg_reject_info.reject_cause ||
        ss_info_gpp_stack_ptr->reg_reject_info.reject_srv_domain != old_srv_info->stack_info[stk_id].reg_reject_info.reject_srv_domain)
    {
      *changed_fields2 |= CM_SS_LU_REJECT_MASK;
      CM_MSG_MED_0 ("GW LU reject info chg");
    }


    /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
    switch(ss_stack_ptr->sys_mode)
    {

      case  SYS_SYS_MODE_LTE:
        if ( !(old_srv_info->stack_info[stk_id].rat_mode_info.lte_mode_info.csg_info.csg_id == SYS_CSG_ID_INVALID && new_srv_info->device_prop.csg_info.csg_id == SYS_CSG_ID_INVALID) &&
             ( 0 != memcmp(&(old_srv_info->stack_info[stk_id].rat_mode_info.lte_mode_info.csg_info), &(new_srv_info->device_prop.csg_info), sizeof(sys_csg_info_s_type)) || \
               ( (new_srv_info->device_prop.csg_info.csg_id != SYS_CSG_ID_INVALID ) && \
                 (ss_stack0_ptr->sys_id.id_type == SYS_SYS_ID_TYPE_UMTS ) && \
                 (!cmss_sys_id_match( ss_stack0_ptr->sys_id, old_srv_info->stack_info[stk_id].sys_id ))))
           )
        {
          changed_fields |= CM_SS_CSG_INFO_CHANGED_MASK;
          CM_MSG_HIGH_1 ("HYBR2 LTE CSG Information Changed. new CSG_ID=%d",new_srv_info->device_prop.csg_info.csg_id);
        }
        break;

      case  SYS_SYS_MODE_GSM:
        if ( !(old_srv_info->stack_info[stk_id].rat_mode_info.gsm_mode_info.csg_info.csg_id == SYS_CSG_ID_INVALID && new_srv_info->device_prop.csg_info.csg_id == SYS_CSG_ID_INVALID) &&
             ( 0 != memcmp(&(old_srv_info->stack_info[stk_id].rat_mode_info.gsm_mode_info.csg_info), &(new_srv_info->device_prop.csg_info), sizeof(sys_csg_info_s_type)) || \
               ( (new_srv_info->device_prop.csg_info.csg_id != SYS_CSG_ID_INVALID ) && \
                 (ss_stack0_ptr->sys_id.id_type == SYS_SYS_ID_TYPE_UMTS ) && \
                 (!cmss_sys_id_match( ss_stack0_ptr->sys_id, old_srv_info->stack_info[stk_id].sys_id ))))
           )
        {
          changed_fields |= CM_SS_CSG_INFO_CHANGED_MASK;
          CM_MSG_HIGH_1 ("HYBR2 GSM CSG Information Changed. new CSG_ID=%d",new_srv_info->device_prop.csg_info.csg_id);
        }
        break;

      case  SYS_SYS_MODE_WCDMA:
        if ( !(old_srv_info->stack_info[stk_id].rat_mode_info.wcdma_mode_info.csg_info.csg_id == SYS_CSG_ID_INVALID && new_srv_info->device_prop.csg_info.csg_id == SYS_CSG_ID_INVALID) &&
             ( 0 != memcmp(&(old_srv_info->stack_info[stk_id].rat_mode_info.wcdma_mode_info.csg_info), &(new_srv_info->device_prop.csg_info), sizeof(sys_csg_info_s_type)) || \
               ( (new_srv_info->device_prop.csg_info.csg_id != SYS_CSG_ID_INVALID ) && \
                 (ss_stack0_ptr->sys_id.id_type == SYS_SYS_ID_TYPE_UMTS ) && \
                 (!cmss_sys_id_match( ss_stack0_ptr->sys_id, old_srv_info->stack_info[stk_id].sys_id ))))
           )
        {
          changed_fields |= CM_SS_CSG_INFO_CHANGED_MASK;
          CM_MSG_HIGH_1 ("HYBR2 CSG Information Changed. new CSG_ID=%d",new_srv_info->device_prop.csg_info.csg_id);
        }
        break;
      default:
        break;

    }
    if(ss_stack0_ptr->sys_mode == SYS_SYS_MODE_LTE)
    {
      if ( old_srv_info->stack_info[stk_id].rat_mode_info.lte_mode_info.voice_support_on_lte !=
           ss_sub_ptr->sub_info.gen_sub_info.dom_sel_info.voice_support_on_lte )
      {
        changed_fields |= CM_SS_VOICE_SUPPORT_ON_LTE_MASK;
      }
    }
    /*lint -restore */


    if((cmss_get_misc_sub_prop_ptr(asubs_id) != NULL &&
        cmss_get_misc_sub_prop_ptr(asubs_id)->stack_info[MM_STACK_2].gpp_info != NULL &&
        cmss_get_misc_sub_prop_ptr(asubs_id)->stack_info[MM_STACK_2].gpp_info->div_duplex != old_srv_info->div_duplex )
        && (cmss_get_misc_sub_prop_ptr(asubs_id)->stack_info[MM_STACK_2].gpp_info->div_duplex != SYS_DIV_DUPLEX_UNKNOWN)
        && (cmss_is_stack2_operational(asubs_id) &&
            cmph_is_lte_capable_on_sub(asubs_id)))
    {
      changed_fields |= CM_SS_DIV_DUPLEX_MASK;
    }

  } /* if ((new_srv_info != NULL) && (old_srv_info != NULL)) */

  return changed_fields;

} /* cmss_get_ss_stack_2_info_change () */

/*===========================================================================

FUNCTION cmss_is_cdma_svd_supported

DESCRIPTION
  This function should be called to check if SVD is supported on 1x.

DEPENDENCIES
  cmss_init() should have been called previously.

RETURN VALUE
  None.

SIDE EFFECTS
  None.
===========================================================================*/
boolean                                         cmss_is_cdma_svd_supported
(
  sys_modem_as_id_e_type  asubs_id
)
{
  cm_mm_ss_info_sub_prop_s_type *ss_sub_ptr = cmss_get_info_sub_prop(asubs_id);
  cm_mm_ss_info_gen_stack_info_s_type *ss_stack_ptr;
  if(ss_sub_ptr == NULL ||
      ss_sub_ptr->stack_info[MM_STACK_0].gen_info == NULL)
  {
    return FALSE;
  }
  ss_stack_ptr = ss_sub_ptr->stack_info[MM_STACK_0].gen_info;

  /* Check if we have service on 1x and ccs is supported.
  */
  if ( sys_srv_status_is_srv(ss_stack_ptr->srv_status) &&
       ss_stack_ptr->sys_mode == SYS_SYS_MODE_CDMA &&
       ss_stack_ptr->mode_info.cdma_info.ccs_supported
     )
  {
    /* CCS supported.
    */
    return TRUE;
  }

  /*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  /* CCS not supported.
  */
  return FALSE;

} /* cmss_is_cdma_svd_supported() */


/*===========================================================================

FUNCTION cmss_get_ss_hdr_info_change

DESCRIPTION
  Compares the serving system information change and returns
  a bit mask holding difference.

DEPENDENCIES
  Phone object must have already been initialized with
  cmph_init().

RETURN VALUE
  Bit Mask indicating which of the Serving System parameters changed

SIDE EFFECTS
  none

===========================================================================*/
static uint64 cmss_get_ss_hdr_info_change(

  const cm_mm_ss_info_s_type     *new_srv_info,
  /*  New SS information */

  const cm_mm_msim_ss_info_s_type     *old_srv_info,
  /*  Old SS information */

  sys_modem_as_id_e_type  asubs_id
)
{
  uint8                                stk_id=cmss_map_stack_id_to_client_stk(MM_STACK_1);

  uint64                        changed_fields = 0;
  /* Records the changes in SS parameters between new_srv_info and old_srv_info */

  const sys_time_info_s_type         *old_time = &(old_srv_info->stack_info[stk_id].mode_info.cdma_info.time_info);

  const sys_time_info_s_type         *new_time = CDMA_TIME_PTR(new_srv_info, asubs_id);
  cm_mm_ss_info_sub_prop_s_type *ss_sub_ptr;
  cm_mm_ss_info_gen_stack_info_s_type *ss_stack1_ptr;
  cm_mm_ss_info_3gpp2_stack_info_s_type *ss_stack1_gpp2_ptr;

  if(new_srv_info == NULL || !cmutil_is_as_id_valid(asubs_id) ||
      new_srv_info->sub_prop[asubs_id] == NULL)
  {
    return changed_fields;
  }
  ss_sub_ptr = new_srv_info->sub_prop[asubs_id];
  ss_stack1_ptr = ss_sub_ptr->stack_info[MM_STACK_1].gen_info;
  ss_stack1_gpp2_ptr = ss_sub_ptr->stack_info[MM_STACK_1].gpp2_info;
  if(ss_stack1_gpp2_ptr == NULL || ss_stack1_ptr == NULL)
  {
    return changed_fields;
  }

  if ((new_srv_info != NULL) && (old_srv_info != NULL))
  {

    CM_MSG_HIGH_2 ("Entering changed fields info for hdr: changed_fields= %d , stk_id = %d",
                   changed_fields,stk_id);

    if (ss_stack1_ptr->srv_status != old_srv_info->stack_info[stk_id].srv_status)
    {
      changed_fields |= CM_SS_HDR_SRV_STATUS_MASK;
    }

    if (ss_stack1_ptr->roam_status != old_srv_info->stack_info[stk_id].roam_status)
    {
      changed_fields |= CM_SS_HDR_ROAM_STATUS_MASK;
    }

    /*
    ** If the HDR system identifier has changed, notify CM clients of the
    ** corresponding event.
    */
    if ( !cmss_sys_id_match( ss_stack1_ptr->sys_id,
                             old_srv_info->stack_info[stk_id].sys_id ) )
    {
      changed_fields |= CM_SS_HDR_SYS_ID_MASK;
    }

    if (ss_sub_ptr->sub_info.gpp2_sub_info.hdr_gen_info.subnet_mask_len!= old_srv_info->stack_info[stk_id].rat_mode_info.hdr_mode_info.subnet_mask_len)
    {
      changed_fields |= CM_SS_HDR_SYS_ID_MASK;
      CM_MSG_MED_0("subnet_mask_len changed");
    }

#ifdef FEATURE_BCMCS
    if( ss_stack1_gpp2_ptr->ss_bcmcs_srv_status !=
          old_srv_info->stack_info[stk_id].bcmcs_srv_status )
    {
      changed_fields |= CM_SS_HYBR_HDR_BCMCS_SRV_STATUS_MASK;
    }
#endif

    /* If throttle status on hybrid HDR
    ** has changed notify CM clients of the corresponding event.
    */
#ifdef FEATURE_CALL_THROTTLE
    if (ss_stack1_gpp2_ptr->gpp2_thr_status.ss_thr_status !=
          old_srv_info->stack_info[stk_id].thr_status.ss_thr_status)
    {
      changed_fields |= CM_SS_ORIG_THR_STATUS_MASK;
    }
#endif


    /* If the HDR active protocol is changed, set the mask.
    */
    if( ss_sub_ptr->sub_info.gpp2_sub_info.hdr_gen_info.hdr_active_prot != old_srv_info->stack_info[stk_id].rat_mode_info.hdr_mode_info.hdr_active_prot )
    {
      changed_fields |= CM_SS_HDR_ACTIVE_PROT_MASK;
    }

    /* If the HDR personality is changed, set the mask.
    */
    if( ss_sub_ptr->sub_info.gpp2_sub_info.hdr_signal_info.hdr_personality != old_srv_info->stack_info[stk_id].rat_mode_info.hdr_mode_info.hdr_personality )
    {
      changed_fields |= CM_SS_HDR_PERSONALITY_MASK;
    }

    /* If the HYBRID active band is changed, set the mask.
    */
    if (ss_stack1_ptr->active_band != old_srv_info->stack_info[stk_id].active_band )
    {
      changed_fields |= CM_SS_HYBRID_ACTIVE_BAND_MASK;
    }

    /* If the HYBRID active channel is changed, set the mask.
    */
    if (ss_stack1_ptr->active_channel != old_srv_info->stack_info[stk_id].active_channel )
    {
      changed_fields |= CM_SS_HYBRID_ACTIVE_CHANNEL_MASK;
    }

    /*
       ** If there is a CDMA time change, notify clients.
       ** The old_time, new_time are defined within a union. Do not allow
       ** accessing them if the previous srv info was of 3GPP.
    */

    if(cmss_is_cdma_time_chgd(old_time,new_time))
    {
      changed_fields |= CM_SS_CDMA_TIME_CHGD_MASK;
    }

  } /* if ((new_srv_info != NULL) && (old_srv_info != NULL)) */
  CM_MSG_HIGH_2 ("changed fields info for hdr: changed_fields= %d , stk_id = %d",
                 changed_fields,stk_id);

  return changed_fields;

} /* cmss_get_ss_hdr_info_change () */

/*===========================================================================

FUNCTION cmss_get_service_status_per_stack

DESCRIPTION
  Copies quick service info into output buffer for given stack.

DEPENDENCIES
  cmss_init()

RETURN VALUE
  None

SIDE EFFECTS
  none

===========================================================================*/
void cmss_get_service_status_per_stack(

  mm_sub_stk_id_s_type  mm_id,
  cm_service_status_s_type *srv_info
  /* Buffer to hold service info for the given stack */
)
{
  sys_modem_as_id_e_type  asubs_id = mm_id.asubs_id;
  multimode_stack_e_type  stack_id = mm_id.stk_id;
  cm_mm_ss_info_sub_prop_s_type *ss_sub_ptr = cmss_get_info_sub_prop(asubs_id);
  cm_mm_ss_info_gen_stack_info_s_type *ss_stack_ptr;

  CM_ASSERT(srv_info != NULL);

  rex_enter_crit_sect(cmtask_crit_sect_ptr());
  if((ss_sub_ptr == NULL || !cmutil_is_as_id_valid(asubs_id)) ||
      stack_id < MM_STACK_0 || stack_id > MM_STACK_2 ||
      ss_sub_ptr->stack_info[stack_id].gen_info == NULL ||
      !ss_sub_ptr->stack_info[stack_id].gen_info->is_stack_operational ||
      ss_sub_ptr->stack_info[stack_id].gen_info->srv_status == SYS_SRV_STATUS_PWR_SAVE)
  {
    srv_info->srv_status = SYS_SRV_STATUS_NO_SRV;
  }
  else
  {
    ss_stack_ptr = ss_sub_ptr->stack_info[stack_id].gen_info;
    srv_info->srv_status = ss_stack_ptr->srv_status;
    srv_info->sys_mode = ss_stack_ptr->sys_mode;
    srv_info->band = ss_stack_ptr->active_band;
    srv_info->chan = ss_stack_ptr->active_channel;
    srv_info->roam_status = ss_stack_ptr->roam_status;
  }
  rex_leave_crit_sect(cmtask_crit_sect_ptr());
} /* cmss_get_service_status_per_stack */


/*===========================================================================

===========================================================================*/

void cmss_get_camped_srv_info(

  mm_sub_stk_id_s_type mm_id,
  sys_srv_status_e_type *srv_status

)
{

  cm_mm_ss_info_sub_prop_s_type *ss_sub_ptr = cmss_get_info_sub_prop(mm_id.asubs_id);
  cm_mm_ss_info_gen_stack_info_s_type *ss_stack_ptr;
  if(ss_sub_ptr == NULL ||
      ss_sub_ptr->stack_info[mm_id.stk_id].gen_info == NULL)
  {
    return;
  }
  ss_stack_ptr = ss_sub_ptr->stack_info[mm_id.stk_id].gen_info;

  *srv_status = ss_stack_ptr->srv_status;

  /* Currently don't have service, CAMP_IND means we're moving to LIMITED */
  if (!sys_srv_status_is_srv(*srv_status))
  {
    *srv_status = SYS_SRV_STATUS_LIMITED;
  }
}

