/*===========================================================================
  FUNCTION cmss_is_ss_in_full_srv

  DESCRIPTION
    Tells if given ss is in full service or not.

  DEPENDENCIES

  RETURN VALUE
    true if in full service
    false if not

  SIDE EFFECTS
    none
===========================================================================*/
boolean cmss_is_ss_in_full_srv(mm_sub_stk_id_s_type mm_id)
{
  sys_srv_status_e_type srv_status = cmss_get_info_srv_status(mm_id.asubs_id, mm_id.stk_id);

  if(sys_srv_status_is_full_srv(srv_status))
  {
    return TRUE;
  }

  return FALSE;

}

/*===========================================================================
  FUNCTION cmss_is_ss_in_lmtd_srv

  DESCRIPTION
    Tells if given ss is in limited service or not.

  DEPENDENCIES

  RETURN VALUE
    true if in full service
    false if not

  SIDE EFFECTS
    none
===========================================================================*/
boolean cmss_is_ss_in_lmtd_srv(mm_sub_stk_id_s_type mm_id)
{
  sys_srv_status_e_type srv_status = cmss_get_info_srv_status(mm_id.asubs_id, mm_id.stk_id);

  if(sys_srv_status_is_lmtd_srv(srv_status))
  {
    return TRUE;
  }

  return FALSE;

}

